INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 100101, "どんなに敵が大勢でも、みんなで\n力を合わせれば絶対大丈夫だよ！\nだから顔を上げてこう！\nごーごー！", "vo_empress_100101_001", 1, "", "vo_empress_100101_001", 0, 4, "ヒヨリ", 1, 1);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 100103, "ううっ、何度も戦う相手もいるけど\nあたし、負けたりなんてしないよ！\n今回だってみんなや騎士くんがいる\nフルパワーでいくよーっ！", "vo_empress_100101_002", 1, "", "vo_empress_100101_002", 0, 4, "ヒヨリ", 1, 2);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 100103, "うぅ…すごい力…！\n…でも、なんだか悲しそう\nこの人の気持ちを知りたい\nだからこそ…勝たなきゃ…！", "vo_empress_100101_003", 2, "", "vo_empress_100101_003", 0, 4, "ヒヨリ", 1, 3);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 100102, "騎士くんの力があれば、\nあたしは絶対負けないよ！\nみんなが笑顔でいられるように\n一緒にがんばろう！", "vo_empress_100101_004", 3, "", "vo_empress_100101_004", 100101, 4, "ヒヨリ", 1, 4);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 100203, "わたしたちの世界のためにも\nこの世界のためにも、\n絶対に負けられない…！\nがんばろうね、騎士クン", "vo_empress_100201_001", 1, "", "vo_empress_100201_001", 0, 4, "ユイ", 1, 5);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 100203, "みんな、怪我したらすぐに教えて！\n…もう誰も失いたくないの\nそのために修行もしたんだから…\n大丈夫、絶対なんとかしてみせる！", "vo_empress_100201_002", 1, "", "vo_empress_100201_002", 0, 4, "ユイ", 1, 6);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 100203, "世界を『書き換え』するなんて…\nそんな未来、寂しいだけだよ…！\nお願い、これ以上みんなを\n傷つけないで…話を聞いて！", "vo_empress_100201_003", 2, "", "vo_empress_100201_003", 0, 4, "ユイ", 1, 7);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 100202, "感じるよ、騎士クンの気持ち…\n抱きしめられてるみたいに\nあったかい…\nぜんぶ終わらせよう！", "vo_empress_100201_004", 3, "", "vo_empress_100201_004", 100201, 4, "ユイ", 1, 8);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 100301, "厳しい戦いになるだろうな\n安心してくれ、何があっても\nキミは守る。…いや、違うな\n一緒に、世界を守ろう", "vo_empress_100301_001", 1, "", "vo_empress_100301_001", 0, 4, "レイ", 1, 9);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 100303, "手ごわい相手ばかりだな…\nだが引き下がるわけにはいかない\nこちらにだって譲れないものが\nあるんだ！", "vo_empress_100301_002", 1, "", "vo_empress_100301_002", 0, 4, "レイ", 1, 10);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 100303, "くっ…なんて力だ…！\n防ぐだけで精一杯…だが、\n例え剣が折れたとしても、\n私は最後まで戦い続ける！", "vo_empress_100301_003", 2, "", "vo_empress_100301_003", 0, 4, "レイ", 1, 11);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 100302, "感じるよ、キミからの愛\nこれがあれば、私はどんな\n敵にだって打ち勝てる！\n見せてやろう、一緒に！", "vo_empress_100301_004", 3, "", "vo_empress_100301_004", 100301, 4, "レイ", 1, 12);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 100401, "ミソギとにいちゃんはこれからも\n世界中を冒険して、ワクワクする\nお宝をたくさん見つけるんだ！\nワルモノなんかに邪魔させないよ！", "vo_empress_100401_001", 1, "", "vo_empress_100401_001", 0, 4, "ミソギ", 1, 13);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 100401, "わわ、なんかヤバそうな雰囲気…\nこういう時こそミソギの出番だね！\nとっておきのイタズラ決めて、\nピンチもひっくり返しちゃうよ！", "vo_empress_100401_002", 1, "", "vo_empress_100401_002", 0, 4, "ミソギ", 1, 14);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 100403, "うぅ…あの悪者、すごい迫力だよ…\nもしミソギたちが負けちゃったら、\nミソギもにいちゃんもこの世界も…\n全部おしまい、なんだよね…？", "vo_empress_100401_003", 2, "", "vo_empress_100401_003", 0, 4, "ミソギ", 1, 15);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 100402, "ミソギたちが世界を救っちゃったら\nきっとみんなびっくりするよね！\nどんな顔して驚いてくれるかな…\nにひひ、なんかワクワクしてきた！", "vo_empress_100401_004", 3, "", "vo_empress_100401_004", 100401, 4, "ミソギ", 1, 16);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 100501, "歴代オールヒーロー大進撃ッス～！\n自分は新世代のエースってとこッス\nかね？　さあ、ついてくるッス……\nあれ？　みんなどこ？　待って～", "vo_empress_100501_001", 1, "", "vo_empress_100501_001", 0, 4, "マツリ", 1, 17);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 100501, "敵は圧倒的な力で、こっちを絶望\nさせる気ッスかね？　だとしたら\n大誤算ッスよ！　むしろ自分の\n正義の魂に火をつけたんスから！", "vo_empress_100501_002", 1, "", "vo_empress_100501_002", 0, 4, "マツリ", 1, 18);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 100503, "足が……震えるッス……けど！\nこれは武者震いッス……！　だって\nヒーローは絶対に絶対にっ！\n敗北なんてしないんスから……っ！", "vo_empress_100501_003", 2, "", "vo_empress_100501_003", 0, 4, "マツリ", 1, 19);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 100502, "さあ、手と手をつないで、\n二人で教えてやるッスよ！\nどんな物語でも、悪は必ずヒーロー\nに打ち倒されるってことを！", "vo_empress_100501_004", 3, "", "vo_empress_100501_004", 100501, 4, "マツリ", 1, 20);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 100603, "ひゃぁんっ！\nもう、敵さんが脅かしてくるから\nアカリ、ヘンな声出ちゃいました…\nこういうの、よくないですよっ", "vo_empress_100601_001", 1, "", "vo_empress_100601_001", 0, 4, "アカリ", 1, 21);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 100601, "アカリ、お兄ちゃんとシタイコトが\nまだまだいっぱいあるんです！\nだから、私たちの大事な世界も…\n本気で守り抜いてみせますっ！", "vo_empress_100601_002", 1, "", "vo_empress_100601_002", 0, 4, "アカリ", 1, 22);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 100603, "うぅ…こんなに激しく攻められたら\nアカリ、もう壊れちゃいそうです…\nだけどまだまだ…戦えますっ！\nお兄ちゃんが一緒なんですからっ…", "vo_empress_100601_003", 2, "", "vo_empress_100601_003", 0, 4, "アカリ", 1, 23);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 100602, "お兄ちゃんの愛を注いでもらって\nアカリ超絶パワーアップです！\nアカリらしく世界一かわいく、\n世界を救ってみせちゃいますよ！", "vo_empress_100601_004", 3, "", "vo_empress_100601_004", 100601, 4, "アカリ", 1, 24);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 100701, "アイツらが野放しだと、ミヤコは\n安心してプリンを食べられないの\n今日のプリンと明日のプリンの\nためにも、絶対負けないの！", "vo_empress_100701_001", 1, "", "vo_empress_100701_001", 0, 4, "ミヤコ", 1, 25);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 100702, "前はミヤコ、悪いヤツに捕まって\n消されそうになって怖かったの…\nでも今度は全然怖くないの！\nオマエが一緒なら平気なの！", "vo_empress_100701_002", 1, "", "vo_empress_100701_002", 0, 4, "ミヤコ", 1, 26);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 100703, "むうぅ～っ、アイツしつこいの！\nこうなったら、オマエにも\nミヤコのプリン分けてやるの！\nダブルプリンパワーで頑張るの！", "vo_empress_100701_003", 2, "", "vo_empress_100701_003", 0, 4, "ミヤコ", 1, 27);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 100702, "アイツはどんなに強くたって、\n独りぼっちのさびしいヤツなの\nでもオマエにはミヤコがいるの！\nミヤコたちなら絶対に勝てるの！", "vo_empress_100701_004", 3, "", "vo_empress_100701_004", 100701, 4, "ミヤコ", 1, 28);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 100801, "相手が誰であれ、やることは同じ…\nそう…ボクの美しさを見せてあげる\nことさ！　予言しよう…絶世の美の\n前にはどんな敵もひれ伏すと、ね！", "vo_empress_100801_001", 1, "", "vo_empress_100801_001", 0, 4, "ユキ", 1, 29);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 100801, "少し待っていてくれる？　メイクを\n直さないと。避けられない戦いなら\nせめて美しいボクと戦えることを\n彼らには誇りに思ってほしいからね", "vo_empress_100801_002", 1, "", "vo_empress_100801_002", 0, 4, "ユキ", 1, 30);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 100801, "どうせ倒れるなら美しいままで散り\nたいな。ふふ、難しい望みかな…？\nそれでもボクは、最後まで美しく\nあがいてみせるよ、キミと一緒にね", "vo_empress_100801_003", 2, "", "vo_empress_100801_003", 0, 4, "ユキ", 1, 31);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 100802, "ボクがいて、キミがいる。ボクたち\nが勝つのに、これ以上の理由はない\nよね。だって美しい者が勝つ未来の\nほうが、美しいエンディングだもの", "vo_empress_100801_004", 3, "", "vo_empress_100801_004", 100801, 4, "ユキ", 1, 32);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 100901, "災厄の嵐が吹き荒れ、世界の命運は\n風前の灯が如く儚い。だが絶望には\nまだ早い！　希望はここに在り！\n灯火を掲げよう、盟友シグルドよ！", "vo_empress_100901_001", 1, "", "vo_empress_100901_001", 0, 4, "アンナ", 1, 33);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 100903, "終焉の日、滅びの刻来たれり、か…\nだが、幾度も転生を繰り返しながら\n戦いつづけた我らの宿命を思えば、\nこの程度取るに足らない…はずだ！", "vo_empress_100901_002", 1, "", "vo_empress_100901_002", 0, 4, "アンナ", 1, 34);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 100903, "くっ…なんという禍々しい魔力…！\nもはや世界の滅びも間近…しかし\n疾風の冥姫がここで退くわけには\nいかぬ！　しぶとく抗ってみせるぞ", "vo_empress_100901_003", 2, "", "vo_empress_100901_003", 0, 4, "アンナ", 1, 35);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 100902, "永遠の盟約で結ばれし魂の伴侶…\n世界を滅ぼさんとする災禍の剣も\nこの絆を断ち切ることはできない！\n覚悟するがいい、幻境竜后！！", "vo_empress_100901_004", 3, "", "vo_empress_100901_004", 100901, 4, "アンナ", 1, 36);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 101001, "【自警団】のギルドマスターとして\nしゃんとして恥ずかしない姿を\n見せなあきまへんなぁ…王子はん\nしゃなりしゃなり、いきまひょ！", "vo_empress_101001_001", 1, "", "vo_empress_101001_001", 0, 4, "マホ", 1, 37);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 101001, "王子はん、服が破れてますえ？\nこれでよし…うん、完璧や♪\n戦いの中でも、王子はんには\n格好良う居てもらいたいさかいに♪", "vo_empress_101001_002", 1, "", "vo_empress_101001_002", 0, 4, "マホ", 1, 38);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 101003, "幻境竜后…大層なお名前してはる\nお后さまが勝負を挑んできはるなら\nうちも、マホマホ王国の姫として…\n正々堂々受けて立ちますえ！", "vo_empress_101001_003", 2, "", "vo_empress_101001_003", 0, 4, "マホ", 1, 39);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 101002, "強い愛で結ばれた王子と姫を\n引き裂くことは誰にもできまへん\n王子はん…ふたりで一緒に！\nハッピーエンドを迎えまひょ！", "vo_empress_101001_004", 3, "", "vo_empress_101001_004", 101001, 4, "マホ", 1, 40);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 101101, "お兄ちゃんがいれば百人力士っ！\n妹パワーも全開でいきますよ～♪\nどんな敵でもドンドンこいですっ！\nあれ？　ちょっと違いました？", "vo_empress_101101_001", 1, "", "vo_empress_101101_001", 0, 4, "リノ", 1, 41);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 101101, "これぞまさに『四面そば』…\n敵多すぎでもう大盛りですけど\n秘密結社の一員として、妹として\nこの世界の平和は守り通しますっ！", "vo_empress_101101_002", 1, "", "vo_empress_101101_002", 0, 4, "リノ", 1, 42);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 101103, "あれが幻境竜后…不思議な服…\nじゃなくて、空気がピリピリです…\nちょっとだけ怖いけど…妹として\n絶対に降参なんてしませんよ！", "vo_empress_101101_003", 2, "", "vo_empress_101101_003", 0, 4, "リノ", 1, 43);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 101102, "私、もう迷いません！\nお兄ちゃんと一緒なら\nどんな敵だって倒しちゃいます！\n妹のポテンシャルは無限大ですよ！", "vo_empress_101101_004", 3, "", "vo_empress_101101_004", 101101, 4, "リノ", 1, 44);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 101201, "どんなに大変な時でもキミと一緒に\nず～っと乗り越えてきたんだもん！\nだからっ、今回もきっと大丈夫！\n私の魔法できらーん☆　だよっ！", "vo_empress_101201_001", 1, "", "vo_empress_101201_001", 0, 4, "ハツネ", 1, 45);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 101202, "力を使いすぎると眠く…スヤァ…\nはっ、いけないいけない！\nキミ、私が寝ちゃったら起こして！\n…お、王子様のキスとかで…", "vo_empress_101201_002", 1, "", "vo_empress_101201_002", 0, 4, "ハツネ", 1, 46);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 101203, "も～！　容赦なさすぎだよぉ！\nそっ、それにさっきまでの戦いの\nせいで、ね、眠気がぁ～っ…\nハ、ハツネちゃん、ピ～ンチ…", "vo_empress_101201_003", 2, "", "vo_empress_101201_003", 0, 4, "ハツネ", 1, 47);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 101202, "幻境竜后さんがどんなに強くても\n今のハツネちゃんは無敵なのだ～！\n大好きなキミと！　シオリンと！\nみんながいる世界を守っちゃうよ！", "vo_empress_101201_004", 3, "", "vo_empress_101201_004", 101201, 4, "ハツネ", 1, 48);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 101301, "この世界にはね、たくさんの人の\n『好き』が詰まってるんだよ\nそれをぶち壊すなんて鬼畜の所業\nナナカちゃんが許しはしないぜ！", "vo_empress_101301_001", 1, "", "vo_empress_101301_001", 0, 4, "ナナカ", 1, 49);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 101301, "見るからにヤバい奴らが勢ぞろい！\nでもみんなの世界が狙われてんのに\n日和ってる奴いる？いねえよなぁ！\n全員ぶっ飛ばして世界を救うぞ！！", "vo_empress_101301_002", 1, "", "vo_empress_101301_002", 0, 4, "ナナカ", 1, 50);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 101303, "あとはラスボスを倒せば勝利ッ！\n第３部完！　…とはいかない感じ？\nていうか逆にピンチな気配？\nどっどうしよう、どうすれば！？", "vo_empress_101301_003", 2, "", "vo_empress_101301_003", 0, 4, "ナナカ", 1, 51);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 101302, "幻境竜后…確かに強敵だったね\nでも今はもう負ける気がしないかな\nだって私は、ただのナナカじゃない\n超ナナカちゃんだから…！", "vo_empress_101301_004", 3, "", "vo_empress_101301_004", 101301, 4, "ナナカ", 1, 52);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 101401, "あちらにもなかなかの陰謀家がいる\nようだね。彼女らの最大の誤算は\nここに希代の名探偵がいることさ！\nさあ助手くん。真実を勝ち取ろう！", "vo_empress_101401_001", 1, "", "vo_empress_101401_001", 0, 4, "カスミ", 1, 53);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 101401, "仕方ない、こうなったら奥の手だ\nミスティ！　セオリー！　…って\nこらぁっ！　変身の最中は待って\nくれるのがお約束だよ！？", "vo_empress_101401_002", 1, "", "vo_empress_101401_002", 0, 4, "カスミ", 1, 54);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 101403, "なっ…なんだい、この悪寒は…\n触れてはならない何か…いいや！\n名探偵たるもの巨悪に恐れをなす\nわけにはいかない。絶対に…！", "vo_empress_101401_003", 2, "", "vo_empress_101401_003", 0, 4, "カスミ", 1, 55);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 101402, "どんな哀しみでさえ、道理を穢す\n理由にしてはならない。さあ、\nお縄につくんだ。史上最大の迷宮\n事件…終わらせるのは…この私だ！", "vo_empress_101401_004", 3, "", "vo_empress_101401_004", 101401, 4, "カスミ", 1, 56);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 101501, "先生は…ううん、先生たちは。\n絶対に負けません。みんなに傷一つ\nつけさせたりはしないわ…！", "vo_empress_101501_001", 1, "", "vo_empress_101501_001", 0, 4, "ミサト", 1, 57);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 101501, "とっても強大な敵ばかりね…\nでも、大丈夫。焦らず落ち着いて\n戦いましょう。先生がついてるわ\n長引いても、あきらめないで…！", "vo_empress_101501_002", 1, "", "vo_empress_101501_002", 0, 4, "ミサト", 1, 58);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 101501, "幻境竜后さんの力…すごいわ…\nううん、怖がってる暇なんてないの\n森のみんなを守るためにも…！\n好き勝手したら「めっ」ですからね", "vo_empress_101501_003", 2, "", "vo_empress_101501_003", 0, 4, "ミサト", 1, 59);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 101502, "あなたと一緒なら\n負けたりなんか絶対にしないわ\n最後の一撃まで、\nがんばりましょうね♪", "vo_empress_101501_004", 3, "", "vo_empress_101501_004", 101501, 4, "ミサト", 1, 60);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 101601, "ツヨそーな敵ばっかりで\nテン下げってカンジだけど\nとりま、うちとヒデサイが\n一緒なら乗り越えられるっしょ！", "vo_empress_101601_001", 1, "", "vo_empress_101601_001", 0, 4, "スズナ", 1, 61);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 101601, "あっ、まってヒデサイ\nマントずれてるから直してあげる\n…よし！　こーゆう時こそ\nおしゃれでテン上げしなきゃね♪", "vo_empress_101601_002", 1, "", "vo_empress_101601_002", 0, 4, "スズナ", 1, 62);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 101601, "おにヤバすぎて超わろ～…でもでも\nどうにかやるしかないっしょ～\n勝利のランウェイ遠すぎだけど\nうちら諦めんのはダメだよね～！", "vo_empress_101601_003", 2, "", "vo_empress_101601_003", 0, 4, "スズナ", 1, 63);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 101602, "アオハルでバイブス爆上げ♪\n今のうちらは、ムテキだよ～\nハッピーで、もにカワな未来だって\n一緒にゲットするしかないっしょ♪", "vo_empress_101601_004", 3, "", "vo_empress_101601_004", 101601, 4, "スズナ", 1, 64);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 101701, "歌ったり踊ったり、\nキミと一緒にやりたいことが\nばんないあるからね～！\n絶対に負けられないさ～！", "vo_empress_101701_001", 1, "", "vo_empress_101701_001", 0, 4, "カオリ", 1, 65);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 101701, "ううっ強そうな敵ばっかりさ～！\n長丁場の戦いにはやっぱりこれよ～\nサーターアンダギー！\n栄養付けて平和を守るさ～♪", "vo_empress_101701_002", 1, "", "vo_empress_101701_002", 0, 4, "カオリ", 1, 66);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 101703, "うぅ～、幻境竜后、でーじ強いね～\n私たちも引き下がる気はないよ～！\nどんなに時間がかかっても、絶対に\n諦めたりしないさ～！　だよね～？", "vo_empress_101701_003", 2, "", "vo_empress_101701_003", 0, 4, "カオリ", 1, 67);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 101702, "キミのくれた情熱が、\n私の中で熱く燃え滾ってるよ！\n最高の一撃、キミに見せるさ～！", "vo_empress_101701_004", 3, "", "vo_empress_101701_004", 101701, 4, "カオリ", 1, 68);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 101801, "学校生活の邪魔はさせないわ\nだって私、みんなの先生だもの\n明日の授業も世界のことも\n全部守ってみせるんだから！", "vo_empress_101801_001", 1, "", "vo_empress_101801_001", 0, 4, "イオ", 1, 69);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 101801, "やん！　なんて手ごわい人たちなの\nでも諦めないわ。難しい問題だって\n落ち着いてやればちゃんと解けるの\n戦いも同じよ…いきましょう！", "vo_empress_101801_002", 1, "", "vo_empress_101801_002", 0, 4, "イオ", 1, 70);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 101803, "これが、幻境竜后さんの力…圧倒\nされちゃいそう。でも、怖がってる\n場合じゃないわ。先生は絶対に、\nここから退かないわ！", "vo_empress_101801_003", 2, "", "vo_empress_101801_003", 0, 4, "イオ", 1, 71);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 101802, "二人の絆があれば、\n怖いものなんてないわ\n先生と力を合わせて─\nいきましょう♪", "vo_empress_101801_004", 3, "", "vo_empress_101801_004", 101801, 4, "イオ", 1, 72);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 102003, "す、すごく強そうな人がいっぱい…\nミミ、怖くてぶるぶるしちゃうけど\nでも泣いちゃったりはしないよっ\nおにいちゃんがいっしょだもん…！", "vo_empress_102001_001", 1, "", "vo_empress_102001_001", 0, 4, "ミミ", 1, 73);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 102003, "プチグリフォンさんもハナちゃんも\nみゅ～ちゃんも…きっとみんな、\nミミのこと応援してくれてるよね\nだからミミも、がんばるよっ…！", "vo_empress_102001_002", 1, "", "vo_empress_102001_002", 0, 4, "ミミ", 1, 74);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 102003, "あ、あの竜の人…本気になったら、\nすごく強そうだよ…！このままじゃ\nみんなもミミたちも負けちゃう…？\nやだ、ミミそんなのいやだよっ…", "vo_empress_102001_003", 2, "", "vo_empress_102001_003", 0, 4, "ミミ", 1, 75);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 102002, "おにいちゃんがくれた元気、\n今度はミミたちから届けようね\nもう大丈夫、心配しないでって…\n世界中の、大切なお友だちに…！", "vo_empress_102001_004", 3, "", "vo_empress_102001_004", 102001, 4, "ミミ", 1, 76);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 102101, "怖い人たちがいっぱいですぅ…！\n…でも、みんな頑張ってる…私も\nベルルちゃんみたいに勇気を出して\n…祝福の音を鳴らしましょう！", "vo_empress_102101_001", 1, "", "vo_empress_102101_001", 0, 4, "クルミ", 1, 77);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 102101, "お兄ちゃん、私、がんばりますぅ\n『ロスト』したお父さんたちの\nためにも…！　怖い時こそ前を見て\n戦ってみせますからっ…！", "vo_empress_102101_002", 1, "", "vo_empress_102101_002", 0, 4, "クルミ", 1, 78);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 102101, "っ…すごい迫力ですぅ…！\nでも…絶望は必ず乗り越えられる\n胸の中の、希望の音色を信じて…\n逃げたりなんか、しませんよぅ…っ", "vo_empress_102101_003", 2, "", "vo_empress_102101_003", 0, 4, "クルミ", 1, 79);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 102102, "みんなに勇気を与えるために\n主役にも英雄にもなってみせますぅ\nお兄ちゃんがいてくれるなら\n私はなんでもできるんです…！", "vo_empress_102101_004", 3, "", "vo_empress_102101_004", 102101, 4, "クルミ", 1, 80);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 102201, "こ、これくらいの敵、問題ないわ！\nほんとはちょっと怖いけど…\nゲームの世界を救うことくらい\nこっちは慣れっこなんだから…！", "vo_empress_102201_001", 1, "", "vo_empress_102201_001", 0, 4, "ヨリ", 1, 81);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 102201, "ここで私たちが負けたら、\n世界が終わっちゃうなんて…\n絶対に認めるわけにはいかないわ！\nアンタも覚悟決めなさいよっ！", "vo_empress_102201_002", 1, "", "vo_empress_102201_002", 0, 4, "ヨリ", 1, 82);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 102203, "ここからが本当の戦いってこと？\nならもう、とことんやってやるわ！\nゲーマーってのは、敵が手強いほど\n燃えてくる生き物なのよ！", "vo_empress_102201_003", 2, "", "vo_empress_102201_003", 0, 4, "ヨリ", 1, 83);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 102202, "絶対に帰りたい理由ができた…\nそう思うだけで、いくらでも力が\n湧いてくるの。これならもう、\n文句なしの勝ち確よねっ！", "vo_empress_102201_004", 3, "", "vo_empress_102201_004", 102201, 4, "ヨリ", 1, 84);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 102301, "私もみんなと一緒に戦うよ！\n悪い人たちはフルスイングで\nあっという間に倒しちゃうから！\n『おうっ！　全員かかってこい！』", "vo_empress_102301_001", 1, "", "vo_empress_102301_001", 0, 4, "アヤネ", 1, 85);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 102303, "本当はちょっとだけ怖いけど…\nぷうきちもお兄ちゃんも一緒だもん\n力を合わせて世界を守っちゃうよ\n絶対に負けないんだから！", "vo_empress_102301_002", 1, "", "vo_empress_102301_002", 0, 4, "アヤネ", 1, 86);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 102303, "ううっあの人、すごく怖いけど\n逃げないよ、戦うって決めたもん\nね、お兄ちゃん、ぷうきち！\n『ここが踏ん張りどころだぞ！』", "vo_empress_102301_003", 2, "", "vo_empress_102301_003", 0, 4, "アヤネ", 1, 87);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 102302, "お兄ちゃんが約束してくれたもん\n今の私ならどんな悪いやつにも\n負けないよ！　宇宙人でもなんでも\n一撃で追い返しちゃうんだから♪", "vo_empress_102301_004", 3, "", "vo_empress_102301_004", 102301, 4, "アヤネ", 1, 88);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 102503, "大変なことになっちゃいましたね…\nで、でも怖がっていられません！\nお嬢さまのことも、あなたのことも\n私が精一杯お支えします！", "vo_empress_102501_001", 1, "", "vo_empress_102501_001", 0, 4, "スズメ", 1, 89);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 102503, "世界の命運がかかってますから\nドジなんてしてられません！\n…って、ああっ！　言ったそばから\nまた魔法が暴走しちゃいましたっ！", "vo_empress_102501_002", 1, "", "vo_empress_102501_002", 0, 4, "スズメ", 1, 90);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 102503, "す、すごい力です…！\nでもお嬢さまや大切な人をおいて\n逃げるわけにはいきません！\nどこまでもお供します…！", "vo_empress_102501_003", 2, "", "vo_empress_102501_003", 0, 4, "スズメ", 1, 91);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 102502, "大切な人と力を合わせれば、\nドジな私でも世界を救えるんです！\n世界規模…いえ、宇宙規模の大掃除\n始めちゃいますよ～っ！", "vo_empress_102501_004", 3, "", "vo_empress_102501_004", 102501, 4, "スズメ", 1, 92);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 102603, "ええー？　こんだけ人数いるならさ\n一人ぐらいいなくても…\n…って空気じゃないわけね\nはいはい、あたしも働きますよー", "vo_empress_102601_001", 1, "", "vo_empress_102601_001", 0, 4, "リン", 1, 93);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 102603, "うぅ…あんなのもうバグでしょ！？\nこんな無理ゲーに参戦したんだもん\n終わったらしばらく働かないから！\nダラダラゴロゴロするからね～！", "vo_empress_102601_002", 1, "", "vo_empress_102601_002", 0, 4, "リン", 1, 94);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 102603, "見てよあのビジュアルさー\nまさにラスボスって感じじゃん…\nでも、どんなゲームでもボスは\n倒せるわけだし…はぁ、やるかー", "vo_empress_102601_003", 2, "", "vo_empress_102601_003", 0, 4, "リン", 1, 95);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 102602, "ここまで来たら後には退けないし\n正真正銘のラスボス戦ってんなら\nあたしも─気合い入れて\n少しぐらいイイとこ見せないとね！", "vo_empress_102601_004", 3, "", "vo_empress_102601_004", 102601, 4, "リン", 1, 96);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 102701, "有象無象のクズ虫が、私たちの\n幸せを阻もうとしているようですね\nあぁ、なんて忌々しいのでしょう…\n残らずすり潰しますわ、クスクス…", "vo_empress_102701_001", 1, "", "vo_empress_102701_001", 0, 4, "エリコ", 1, 97);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 102701, "クスクス…あら、失礼しましたわ\nこの連中を駆逐すれば、私たちの\n絆はより強く…そんな想像をしたら\n思わず…クスクスクス、クスクス", "vo_empress_102701_002", 1, "", "vo_empress_102701_002", 0, 4, "エリコ", 1, 98);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 102703, "あの女…下らない言葉であなた様を\n誑かそうとしたとか。万死に値する\n罪…身の程を思い知らせてやるまで\n決して退きはしませんわ…", "vo_empress_102701_003", 2, "", "vo_empress_102701_003", 0, 4, "エリコ", 1, 99);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 102702, "『壊し屋』と呼ばれる私ですが…\n今はこの力、創るために振るいます\nあなた様との愛、未来…\nクスクス…さあ参りましょう…♪", "vo_empress_102701_004", 3, "", "vo_empress_102701_004", 102701, 4, "エリコ", 1, 100);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 102801, "しっかり頭数揃えてきたわね…\nでもこの程度の力に屈するような\nあたしたちじゃないんだから\nあんたも、サポート頼んだわよ！", "vo_empress_102801_001", 1, "", "vo_empress_102801_001", 0, 4, "サレン", 1, 101);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (3, 10000, 102801, "ちょっと！　なんか向こうに\n教育に悪そうなのがいるんだけど！\nあいつは子どもたちの目に入る前に\nあたしたちで倒すわよ。いい？", "vo_empress_102801_002", 4002, 1, "vo_empress_102801_002", 0, 4, "サレン", 1, 102);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 102803, "もう、強すぎて参っちゃうわね…\nでも諦めるわけにはいかないわ\nこっちだって守らなきゃいけない\nものがたくさんあるんだから！", "vo_empress_102801_003", 2, "", "vo_empress_102801_003", 0, 4, "サレン", 1, 103);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 102802, "いつも以上に負ける気がしないわ\nこれもあんたと気持ちが通じた\nおかげね。あんたが側にいる限り、\nあたしはずっと無敵なんだから！", "vo_empress_102801_004", 3, "", "vo_empress_102801_004", 102801, 4, "サレン", 1, 104);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 102903, "この世界が終わっちゃうって…\nアイドル活動も卒業ってコト！？\nファンのみんなが黙ってないよ！\nもちろん私だって…！", "vo_empress_102901_001", 1, "", "vo_empress_102901_001", 0, 4, "ノゾミ", 1, 105);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 102903, "どんな強い敵にだって屈しない…\n歌って踊って戦うアイドルになる！\nあの日に誓った願い、私の希望！\n今こそ、果たして見せるんだから！", "vo_empress_102901_002", 1, "", "vo_empress_102901_002", 0, 4, "ノゾミ", 1, 106);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 102903, "幻境竜后…ダンスも歌も、あなたに\nとって価値はないかもしれないけど\n私はこのステージから逃げたり\nなんてしない！　アイドルとして！", "vo_empress_102901_003", 2, "", "vo_empress_102901_003", 0, 4, "ノゾミ", 1, 107);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 102901, "星を書き換えるなんてすごい発想…\nプロデューサーとか向いてるかも？\nって、今はそんな場合じゃないか！\n覚悟してよね、幻境竜后！", "vo_empress_102901_004", 3, "", "vo_empress_102901_004", 102901, 4, "ノゾミ", 1, 108);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 103001, "ショーグンの天下統一を阻む者は\n誰であろうと許しまセン！\nショーグン！　ここはチューシン\nニノンにお任せアーレー！", "vo_empress_103001_001", 1, "", "vo_empress_103001_001", 0, 4, "ニノン", 1, 109);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 103001, "むむむ…待ち受けているのは強敵\nばかり…それでも退きまセン！\n超烈火之紅蓮旋風で、\nまとめて討ち取ってみせまショウ！", "vo_empress_103001_002", 1, "", "vo_empress_103001_002", 0, 4, "ニノン", 1, 110);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 103003, "な、なんて強さ…このままでは、\nワタシたちは負けてしまいます…\n…いいえ。いいえ！　ショーグンの\nためにも、諦めることなど…っ！", "vo_empress_103001_003", 2, "", "vo_empress_103001_003", 0, 4, "ニノン", 1, 111);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 103002, "感じマス、ショーグンの愛を…！\n今ならどんな敵が来ても、\nカッサイ、ボンサイ、\nオチャノコサイサイデース！", "vo_empress_103001_004", 3, "", "vo_empress_103001_004", 103001, 4, "ニノン", 1, 112);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 103101, "この世界が、明日を迎えることなく\n滅んでしまうかもしれない…\n運命の岐路が、目の前にあります\n抗えるのは、私たちだけです…！", "vo_empress_103101_001", 1, "", "vo_empress_103101_001", 0, 4, "シノブ", 1, 113);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 103101, "何よりも色濃い死の気配が、\n世界に満ちていくのを感じます\nでも、倒れるわけにはいきません\n最後まで戦いましょう、全力で", "vo_empress_103101_002", 1, "", "vo_empress_103101_002", 0, 4, "シノブ", 1, 114);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 103103, "これほどまでに強大な力なんて…\n占いも、未来は滅びの闇に覆われ\nつつある、と出ています…それでも\n希望を手放すわけには…！", "vo_empress_103101_003", 2, "", "vo_empress_103101_003", 0, 4, "シノブ", 1, 115);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 103101, "命ある者にとって、死の運命は\n決して避けられないもの…\nでも、今この時ではないはずです\n戦いましょう、未来のために…！", "vo_empress_103101_004", 3, "", "vo_empress_103101_004", 103101, 4, "シノブ", 1, 116);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 103201, "これ以上の狼藉は許しません！\nウィスタリア家の名に懸けて、\nこの世界の人々を守ります…必ずや\n貴人としての役目を果たしますわ！", "vo_empress_103201_001", 1, "", "vo_empress_103201_001", 0, 4, "アキノ", 1, 117);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 103201, "互いを利するウィンウィンの関係\nそれが商売の鉄則です。力を振るい\n一方的に望みを押し付けるなんて、\n倒産まっしぐらですわよっ！", "vo_empress_103201_002", 1, "", "vo_empress_103201_002", 0, 4, "アキノ", 1, 118);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 103203, "幻境竜后…すさまじい力ですわね\n世界を意のままにするという野望も\n決して絵空事ではないのでしょう…\nそれでも私は…諦めませんわよ！", "vo_empress_103201_003", 2, "", "vo_empress_103201_003", 0, 4, "アキノ", 1, 119);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 103202, "人々を守ることが力ある者の務め…\nそしてあなたさまと共に生きること\nそれが私の務めであり願いですわ！\nこの想いは、止まりませんわよ！", "vo_empress_103201_004", 3, "", "vo_empress_103201_004", 103201, 4, "アキノ", 1, 120);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 103301, "こんな舞台で漫才したって\nみんなもお天道さんもどんよりだべ\n安心して笑ってられる世界を\nオラたちで取り戻すど！　おー！", "vo_empress_103301_001", 1, "", "vo_empress_103301_001", 0, 4, "マヒル", 1, 121);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 103301, "お、おっかねぇ連中だ…！\nでも…スベっちまう怖さに比べりゃ\nマシだべな！　あははっ！\nみんなの笑顔は、オラが守るべ！", "vo_empress_103301_002", 1, "", "vo_empress_103301_002", 0, 4, "マヒル", 1, 122);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 103303, "あの子、芸人として光りそうだべな\n幻境竜后なんて仰々しい名前も…\nノーヴィジョンズノープロブレム！\n…あたた！　激しいツッコミだべ！", "vo_empress_103301_003", 2, "", "vo_empress_103301_003", 0, 4, "マヒル", 1, 123);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 103302, "逆境も笑顔で切り開く…\nあんちゃんと一緒なら\nできる気がすんだ\nオラたちの芸人魂、見せてやるべ！", "vo_empress_103301_004", 3, "", "vo_empress_103301_004", 103301, 4, "マヒル", 1, 124);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 103401, "元…ううん、正しき聖騎士として\nここでやらなきゃいつやるのよ…！\n必ずみんなを守りきってみせるわ\n怪我をした人は私のところへ！", "vo_empress_103401_001", 1, "", "vo_empress_103401_001", 0, 4, "ユカリ", 1, 125);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 103401, "…んぐっ…ごくっ…ぷは～っ♪\nよぉし気合十分らわ～っ！\nこら～幻境竜后～っ！　隠れて\nないでかかってきなさ～い！", "vo_empress_103401_002", 1, "", "vo_empress_103401_002", 0, 4, "ユカリ", 1, 126);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 103403, "ひっく…ふぇ？　な、なに……？\nと、とっても大きいのが見えりゅ…\n…なっ、なによこれえぇぇ！\nこ、これが幻境竜后の姿なのぉ～っ", "vo_empress_103401_003", 2, "", "vo_empress_103401_003", 0, 4, "ユカリ", 1, 127);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 103402, "私は無敵らのよ～♪　この世界と\nキミと築く\n素敵な未来のために…幻境竜后！\nぶっとばしてやるわぁ～っ！", "vo_empress_103401_004", 3, "", "vo_empress_103401_004", 103401, 4, "ユカリ", 1, 128);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 103603, "ここで私たちが諦めたら、このまま\n世界が終わっちゃう！　そんなの\n絶対ダメです！　負けられません！\n私たちで全部退治しちゃいますよ！", "vo_empress_103601_001", 1, "", "vo_empress_103601_001", 0, 4, "キョウカ", 1, 129);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 103603, "うぅ、ふしんしゃがいっぱいです！\n…でも、このくらいへっちゃらです\nお母さんが心配する前に、早く\n片付けておうちに帰りましょう！", "vo_empress_103601_002", 1, "", "vo_empress_103601_002", 0, 4, "キョウカ", 1, 130);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 103601, "あれが私たちの敵、幻境竜后…\nほ、本当に勝てるんでしょうか…？\n立ってるだけで体が震えて…でも、\n弱気になっちゃダメですよねっ…！", "vo_empress_103601_003", 2, "", "vo_empress_103601_003", 0, 4, "キョウカ", 1, 131);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 103602, "正直に言うと…まだ少し怖いです\n我慢したって怖くて体が震えます\nでも、あなたがいてくれるから…\n勇気だって同じくらい湧いてきます", "vo_empress_103601_004", 3, "", "vo_empress_103601_004", 103601, 4, "キョウカ", 1, 132);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 103701, "滅ぼすための力に、守るための力が\n屈するわけにはいかないよ。\nこの剣の誇りに賭けて、必ず止める\nさあ、来い！　ミクマ流が相手だ！", "vo_empress_103701_001", 1, "", "vo_empress_103701_001", 0, 4, "トモ", 1, 133);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 103701, "追いかけっこでもしようか\n鬼さんこちら♪　…って、まだ\n来るの！？　不意打ちされる側に\nなるのは趣味じゃないんだけどな！", "vo_empress_103701_002", 1, "", "vo_empress_103701_002", 0, 4, "トモ", 1, 134);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 103701, "踏み込めない…踏み込む隙がない…\n向きあってるだけで精一杯なんて…\nで、でも…こんなところで\n剣を捨てるわけにはっ…！", "vo_empress_103701_003", 2, "", "vo_empress_103701_003", 0, 4, "トモ", 1, 135);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 103702, "勝機は私の中にあったんだ…！\nあなたとの、\n一番強くて絶対に消えない絆\nそれが、あいつを倒す力をくれる！", "vo_empress_103701_004", 3, "", "vo_empress_103701_004", 103701, 4, "トモ", 1, 136);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 103801, "手ごわい相手ですね…\nでも、不思議と怖くありません\nあなたと力を合わせれば\n何とかなるって信じていますから", "vo_empress_103801_001", 1, "", "vo_empress_103801_001", 0, 4, "シオリ", 1, 137);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 103801, "あなたの応援で、私の胸に\n愛と希望が満ち溢れています…\n今こそ魔法狩人ピュアリー★シオリ\nに大変身する時なのかも…？", "vo_empress_103801_002", 1, "", "vo_empress_103801_002", 0, 4, "シオリ", 1, 138);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 103803, "とてつもない力ですね…\nでも、諦めたくありません\n何度だって立ち上がってみせます\n今までと同じように…！", "vo_empress_103801_003", 2, "", "vo_empress_103801_003", 0, 4, "シオリ", 1, 139);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 103802, "今の私に怖いものなんてありません\nあなたとの愛の力がありますから♪\n…少し舞い上がり過ぎですかね？\nふふ、気を引き締めてがんばります", "vo_empress_103801_004", 3, "", "vo_empress_103801_004", 103801, 4, "シオリ", 1, 140);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 104001, "進んで目立ちたくはないですけど…\nと、ともっ…友達を守るためなら！\nＢＢ団として、勇気を振り絞って…\n団長さんと一緒に戦います！", "vo_empress_104001_001", 1, "", "vo_empress_104001_001", 0, 4, "アオイ", 1, 141);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 104002, "いいい、一緒に戦う仲間がこんなに\nいてくれるなんて、こ、心強いの\n助太郎～っ！　私も末席で参加し…\nじゃなくてっ！　全力で戦います！", "vo_empress_104001_002", 1, "", "vo_empress_104001_002", 0, 4, "アオイ", 1, 142);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 104003, "ううっ、手も足も声も震えてます…\nで、でも逃げも隠れもしませんよっ\n逃げたらぼっちが廃ります！", "vo_empress_104001_003", 2, "", "vo_empress_104001_003", 0, 4, "アオイ", 1, 143);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 104002, "私はひとりぼっちじゃない…\n団長さんと繋がった絆があるから\nどんな敵だって怖くないですっ！\n行きましょう、団長さんっ！", "vo_empress_104001_004", 3, "", "vo_empress_104001_004", 104001, 4, "アオイ", 1, 144);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 104203, "やめてくれる気はなさそうです\nそれなら私も、絶対にここを\n動きはしません…！　だって\n私は……ワガママですからっ！", "vo_empress_104201_001", 1, "", "vo_empress_104201_001", 0, 4, "チカ", 1, 145);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 104201, "私の唱喚術は人を守るためのもの…\nこの世界の森羅万象を護るための\nもの。今こそ、声の限り歌います\nこの子たちと、あなたと共に！", "vo_empress_104201_002", 1, "", "vo_empress_104201_002", 0, 4, "チカ", 1, 146);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 104203, "精霊たちが震えてる…今までの\n敵とは訳が違うってことですよね…\n私もここに立っているのが精一杯…\n怖いけど…でも！　退きません…！", "vo_empress_104201_003", 2, "", "vo_empress_104201_003", 0, 4, "チカ", 1, 147);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 104201, "今なら歌える気がします。ずっと\n探していた、誰かの心を震わせる歌\n幻境竜后…孤独なあなたの心にも\n私たちの歌が届くように…！", "vo_empress_104201_004", 3, "", "vo_empress_104201_004", 104201, 4, "チカ", 1, 148);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 104301, "敵さんがどんだけ強くったって\n後には退けねぇんだ！　そうだろ、\nさぁ、覚悟しやがれよ！", "vo_empress_104301_001", 1, "", "vo_empress_104301_001", 0, 4, "マコト", 1, 149);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 104301, "くっ、敵の連中、ずいぶんな戦力\n揃えてきやがった。けど、\n数でも気合でも負けやしねぇ！\nあたしが嚙み砕いてやる！", "vo_empress_104301_002", 1, "", "vo_empress_104301_002", 0, 4, "マコト", 1, 150);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 104303, "幻境竜后とやら…マジで\n洒落になんねえな。だからって\n引き下がるわけにゃいかねえ！\n持ちこたえてやるぜ！", "vo_empress_104301_003", 2, "", "vo_empress_104301_003", 0, 4, "マコト", 1, 151);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 104302, "どんな強い敵でも\n恐れる必要なんてないよな\nさあ、いっしょに─最大パワーで\nブチのめしてやろうぜっ！", "vo_empress_104301_004", 3, "", "vo_empress_104301_004", 104301, 4, "マコト", 1, 152);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 104401, "ここはいずれわらわが支配する世界\nつまり、わが領地に等しきもの…\n奴らのような不届き者の蛮行、\n見過ごすわけにはいかぬわ！", "vo_empress_104401_001", 1, "", "vo_empress_104401_001", 0, 4, "イリヤ", 1, 153);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 104401, "厳しい戦いになりそうじゃな…\nお主もわらわから離れるでないぞ\nも、もちろん、大人の姿を保つのに\n都合がいいからというだけじゃ！", "vo_empress_104401_002", 1, "", "vo_empress_104401_002", 0, 4, "イリヤ", 1, 154);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 104401, "何とも恐ろしく禍々しい力じゃ…\nだが、我が意志は決して挫けぬ\n高貴なる吸血鬼の誇りに懸けて、\n最後まで戦い抜いてみせようぞ", "vo_empress_104401_003", 2, "", "vo_empress_104401_003", 0, 4, "イリヤ", 1, 155);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 104401, "己が誰を敵に回したのかを、\n骨の髄まで知らしめてやろうぞ\nここにいるのは固き絆で結ばれし\n伝説の吸血鬼とその眷属じゃ！", "vo_empress_104401_004", 3, "", "vo_empress_104401_004", 104401, 4, "イリヤ", 1, 156);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 104501, "とっても強そうな敵ですっ…\n当然、攻撃も強烈になるはず…\nドＳさん、ここはどうかクウカに、\n先頭をお任せください！　ぐふふ♪", "vo_empress_104501_001", 1, "", "vo_empress_104501_001", 0, 4, "クウカ", 1, 157);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 104501, "安心してドＳさんに虐げてもらう\nためにもクウカは負けられませんっ\nこの世界で一番のドＭとして、\n全力で責められに行ってきますっ！", "vo_empress_104501_002", 1, "", "vo_empress_104501_002", 0, 4, "クウカ", 1, 158);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 104503, "ううっ、刺激が強すぎますよ…っ\nだけど、ドＭのプライドにかけて\nここで退くわけにはいきませんっ！\nドＳさんのこと、守り抜きます…っ", "vo_empress_104501_003", 2, "", "vo_empress_104501_003", 0, 4, "クウカ", 1, 159);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 104502, "その視線は、『全部終わったらたっ\nぷり調教してやるからな』という\n意味ですね！　ぐふふっ…♪　負け\nられない理由がまた一つできました", "vo_empress_104501_004", 3, "", "vo_empress_104501_004", 104501, 4, "クウカ", 1, 160);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 104601, "強そうなやつらが目白押しにゃ～\n短期戦でどうにかならないなら…\n長丁場に向けて、特別価格の\nたい焼きはいかがかにゃ～？", "vo_empress_104601_001", 1, "", "vo_empress_104601_001", 0, 4, "タマキ", 1, 161);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 104601, "ファントムキャッツは\n狙った獲物を逃がさないにゃ！\nあたしたちの未来を手に入れるまで\nとことんやってやるにゃ～！", "vo_empress_104601_002", 1, "", "vo_empress_104601_002", 0, 4, "タマキ", 1, 162);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 104603, "にゃにゃっ、これが幻境竜后…\nとんでもない力だにゃ\nでも、ここで逃げたらファントム\nキャッツの名が廃るにゃ～！", "vo_empress_104601_003", 2, "", "vo_empress_104601_003", 0, 4, "タマキ", 1, 163);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 104602, "ファントムキャッツにかかれば\nどんなに強い悪党でも\n滅びる運命にゃ！\nとっておきの一撃、キメるにゃ～！", "vo_empress_104601_004", 3, "", "vo_empress_104601_004", 104601, 4, "タマキ", 1, 164);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 104701, "全軍展開！　敵の一体たりとも\nこの先へは進ませるな\n苦しいときは、私の背中を見るんだ\n我々は決して折れはしない！", "vo_empress_104701_001", 1, "", "vo_empress_104701_001", 0, 4, "ジュン", 1, 165);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 104701, "少年…\n最前線は危険だが、下がるつもりは\nないのか？　ふふ、やはり強情だな\nならば、私の隣を絶対に離れるな", "vo_empress_104701_002", 1, "", "vo_empress_104701_002", 0, 4, "ジュン", 1, 166);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 104701, "な…なんだ…この冷たい闘気は…！\nみんな、いったん退がれ！\n安心しろ、ここは私が防ぎきる\n…たとえ…この身に代えても", "vo_empress_104701_003", 2, "", "vo_empress_104701_003", 0, 4, "ジュン", 1, 167);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 104701, "幻境竜后、貴様は絶対に勝てないよ\n自分の身以上に、大切な誰かを\n守りたいという、人間の持つ尊い\n想いを、知ることのない貴様は…！", "vo_empress_104701_004", 3, "", "vo_empress_104701_004", 104701, 4, "ジュン", 1, 168);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 104801, "バイト仲間とこの世界のみんなを\n守るために！　私たちのやるべき\nことはただ一つ！　いいわね？\n─最高の効率で倒すわよ！", "vo_empress_104801_001", 1, "", "vo_empress_104801_001", 0, 4, "ミフユ", 1, 169);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 104801, "相手も数が多いし、短期決戦とは\nいかないわね…って！　早く\n勝たなきゃバイトに遅刻しちゃう\nもっと効率アップしていくわよ！", "vo_empress_104801_002", 1, "", "vo_empress_104801_002", 0, 4, "ミフユ", 1, 170);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 104803, "幻境竜后……本当に圧倒的な力ね\nだからってそう簡単に諦められる\nわけはないわよね。たとえそれが\n非効率的な判断だとしても……！", "vo_empress_104801_003", 2, "", "vo_empress_104801_003", 0, 4, "ミフユ", 1, 171);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 104802, "こんなに迂遠で非効率的な計画を\n立てる敵になんて負けないわ！\n効率を極めた私たちの一撃を\n叩きつけてやりましょう！", "vo_empress_104801_004", 3, "", "vo_empress_104801_004", 104801, 4, "ミフユ", 1, 172);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 104902, "安心していいよ、弟くん♪\n弟くんには指一本触れさせない！\n絶対に弟くんを守るから…だって\nそれがお姉ちゃんの役目だもんね！", "vo_empress_104901_001", 1, "", "vo_empress_104901_001", 0, 4, "シズル", 1, 173);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 104902, "準備はできてる、弟くん？\n不安なら手をつないであげよっか？\n大丈夫、お姉ちゃんと弟くんなら\n悪いやつらを全部倒せるはず♪", "vo_empress_104901_002", 1, "", "vo_empress_104901_002", 0, 4, "シズル", 1, 174);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 104903, "幻境竜后…手強そうだね…\nでも諦めないよ、絶対に！\n弟くんとお姉ちゃんの大切な世界\nきっと守り抜いてみせるんだから！", "vo_empress_104901_003", 2, "", "vo_empress_104901_003", 0, 4, "シズル", 1, 175);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 104902, "お姉ちゃんと弟くんの力を合わせて\n二人の未来を、みんなの未来を\n一緒に守ろっ！　あ、終わったら\nたくさん甘えさせてあげるからね♪", "vo_empress_104901_004", 3, "", "vo_empress_104901_004", 104901, 4, "シズル", 1, 176);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 105001, "アブナイキレイなお姉さんはね\n『ふれーばー』だから許されるの！\nこんなメチャクチャにするなんて…\n本物の大人のレディが勝負よ勝負！", "vo_empress_105001_001", 1, "", "vo_empress_105001_001", 0, 4, "ミサキ", 1, 177);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 105001, "アタシは全世界代表の\n大人のレディなんだから！\nアンタ！\nしっかりエスコートしてよね！", "vo_empress_105001_002", 1, "", "vo_empress_105001_002", 0, 4, "ミサキ", 1, 178);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 105003, "コ、コイツが幻境竜后…っ\n…正直怖いけど…絶対に逃げないわ\n大人のレディのプライドにかけて\n戦い抜いてやるんだから…！", "vo_empress_105001_003", 2, "", "vo_empress_105001_003", 0, 4, "ミサキ", 1, 179);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 105002, "終わったらデートよ！　だって…\n約束があった方がやる気出るもん♪\nよーし！　大人のレディとして\n最後はエレガントに決めるわよ！", "vo_empress_105001_004", 3, "", "vo_empress_105001_004", 105001, 4, "ミサキ", 1, 180);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 105101, "なんて重圧かしら…でも、あいにく\n私も伊達に修羅場をくぐってないの\nさあ、かかってきなさい！\n裏の人生経験、見せてあげるわ…♪", "vo_empress_105101_001", 1, "", "vo_empress_105101_001", 0, 4, "ミツキ", 1, 181);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 105101, "私は闇医者である前に科学者なの\nあなたたち、実験に協力してくれる\nわよね？　隻眼の悪魔の名は\n伊達じゃないのよ？　覚悟しなさい", "vo_empress_105101_002", 1, "", "vo_empress_105101_002", 0, 4, "ミツキ", 1, 182);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 105101, "到底不可能に思える挑戦こそ\n科学者の腕の見せどころなのよ\n青い薔薇のごとく、人の信念が\n起こす奇跡を見せてあげるわ…！", "vo_empress_105101_003", 2, "", "vo_empress_105101_003", 0, 4, "ミツキ", 1, 183);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 105101, "迷いのない言葉をもらったんだもの\n私だってもう、覚悟を決めたわ\nこの先の未来を君と生きていく…\nそのために全力をぶつけるだけよ！", "vo_empress_105101_004", 3, "", "vo_empress_105101_004", 105101, 4, "ミツキ", 1, 184);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 105201, "私のお友達をいじめるなら\n相手になるわ！\nたとえ魔物に間違えられても\n絶対にここを引かないから！", "vo_empress_105201_001", 1, "", "vo_empress_105201_001", 0, 4, "リマ", 1, 185);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (3, 10000, 105201, "ね、ねぇ…\nちょっと聞きたいんだけど\n毛皮もないのにあの姿なのよね？\n風邪引いたりしないのかしら？", "vo_empress_105201_002", 4002, 1, "vo_empress_105201_002", 0, 4, "リマ", 1, 186);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 105201, "ひづめは割れちゃいそうだし…\n毛並みだってボロボロだし…\nでも後ろには彼がいるんだもの\n恋する乙女の負けられない戦いよ！", "vo_empress_105201_003", 2, "", "vo_empress_105201_003", 0, 4, "リマ", 1, 187);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 105202, "私はもう恋する女の子じゃないわ…\n王子様の愛を受け取ったお姫様よ！\n彼が私を守ってくれるように\n私が彼を守ってみせるわ！", "vo_empress_105201_004", 3, "", "vo_empress_105201_004", 105201, 4, "リマ", 1, 188);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 105303, "どれほど強大な敵であろうと、\n我々【ヴァイスフリューゲル\nランドソル支部】がいれば安心…\nこら！　皆纏まって行動しろー！", "vo_empress_105301_001", 1, "", "vo_empress_105301_001", 0, 4, "モニカ", 1, 189);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 105301, "敵戦力は強大無比…だが、\n私たちなら必ず倒せるはずだ！\n白き翼の名のもとに、今こそ\n正義の鉄槌を下してやる！", "vo_empress_105301_002", 1, "", "vo_empress_105301_002", 0, 4, "モニカ", 1, 190);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 105301, "これが幻境竜后の底力か…\n名にし負う圧倒的な強さだな…\nだが！　長期戦になろうとも必ずや\n私たちが勝利の旗を掲げるのだ！", "vo_empress_105301_003", 2, "", "vo_empress_105301_003", 0, 4, "モニカ", 1, 191);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 105302, "貴公と一緒ならば\nなんだってできるとも\nさあ、最後の一撃を加えてやろう！", "vo_empress_105301_004", 3, "", "vo_empress_105301_004", 105301, 4, "モニカ", 1, 192);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 105401, "強そうな相手ばかりですけど\nだからなんだっていうんですか！\nほら、騎士さんも気合い入れて！\n一緒に戦いますよ！", "vo_empress_105401_001", 1, "", "vo_empress_105401_001", 0, 4, "ツムギ", 1, 193);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (3, 10000, 105403, "なんか敵に下着姿…っていうか\nほぼ裸みたいな人いません？\n…え？　あれ趣味なんですか？\nあの人の？　…正気ですか？", "vo_empress_105401_002", 4002, 1, "vo_empress_105401_002", 0, 4, "ツムギ", 1, 194);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 105403, "世界を作り変えようなんて\n幻境竜后、絶対許せません…！\nあとその服！　そんなに破いて！\nデザイナーが泣いてますよ！", "vo_empress_105401_003", 2, "", "vo_empress_105401_003", 0, 4, "ツムギ", 1, 195);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 105401, "私と騎士さんの糸は\n絶対に切れません！\nだから…今ここで\nすべてを終わらせましょう！", "vo_empress_105401_004", 3, "", "vo_empress_105401_004", 105401, 4, "ツムギ", 1, 196);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 105503, "つ、強そうな人たちばっかり…\n逃げたいくらいだけど、\nそれはダメ。先輩をケガさせない\nためにも、私も頑張らなくちゃ！", "vo_empress_105501_001", 1, "", "vo_empress_105501_001", 0, 4, "アユミ", 1, 197);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 105501, "私なんかが大それたことを言うのは\n笑われるかも…でも…！\n先輩を守るために、\n世界を守ってみせます…！", "vo_empress_105501_002", 1, "", "vo_empress_105501_002", 0, 4, "アユミ", 1, 198);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 105503, "な、なんて大きさ、存在感…！\nまるで私とは真逆の人…\nこうして立ってるだけで、\n私、消えちゃいそうです～っ…！", "vo_empress_105501_003", 2, "", "vo_empress_105501_003", 0, 4, "アユミ", 1, 199);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 105502, "先輩がそばにいてくれる…\nそれだけで勇気が湧いてきて\n前へ進む力がもらえるんです\n行きましょう、先輩！", "vo_empress_105501_004", 3, "", "vo_empress_105501_004", 105501, 4, "アユミ", 1, 200);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 105601, "雁首並べてよくもまあ…\nこりゃ長丁場になりそうだ\n釣りと同じくじっくり腰を据えて\n勝負しようじゃないか", "vo_empress_105601_001", 1, "", "vo_empress_105601_001", 0, 4, "ルカ", 1, 201);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 105601, "世界の危機とあっちゃあ\nアタシたち黄昏時の住人でも\n黙っちゃいられないね！\nひとっ働きさせてもらおうかい！", "vo_empress_105601_002", 1, "", "vo_empress_105601_002", 0, 4, "ルカ", 1, 202);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 105603, "へぇ、これが幻境竜后かい…\nたいそうな強さだけど、アタシも\nここで退くわけにはいかないんだ\n心に差した刃に懸けて、いくよ！", "vo_empress_105601_003", 2, "", "vo_empress_105601_003", 0, 4, "ルカ", 1, 203);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 105602, "刀も恋も揃ったアタシは天下無双！\nお前さんが側にいてくれれば、\nどんな巨悪にだって勝てるよ！", "vo_empress_105601_004", 3, "", "vo_empress_105601_004", 105601, 4, "ルカ", 1, 204);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 105803, "また一緒に、みんなで\nおいしいごはんを食べるために！\nわたしたちは、絶対に負けません！", "vo_empress_105801_001", 1, "", "vo_empress_105801_001", 0, 4, "ペコリーヌ", 1, 205);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (3, 10000, 105801, "フレイヤさんだけじゃなく、\n覇瞳皇帝やミロクまで！\n長丁場になりそうです…\n栄養補給はしっかりしましょうね！", "vo_empress_105801_002", 4003, 1, "vo_empress_105801_002", 0, 4, "ペコリーヌ", 1, 206);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 105803, "これが、幻境竜后の力…\nやばいですね。正直、どうやって\n止めればいいのか分かりません\nでもここで引き下がるわけには…っ", "vo_empress_105801_003", 2, "", "vo_empress_105801_003", 0, 4, "ペコリーヌ", 1, 207);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 105802, "あなたの愛情でお腹いっぱいの\n無敵ペコリーヌ参上です☆\nわたしたちの明日を、この世界を\n全力全開で取り戻しましょう！", "vo_empress_105801_004", 3, "", "vo_empress_105801_004", 105801, 4, "ペコリーヌ", 1, 208);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 105903, "みなさまとのおいしいごはんのため\n負けるわけにはまいりません\n主さま、お背中はお任せください\nわたくしがお守りいたします！", "vo_empress_105901_001", 1, "", "vo_empress_105901_001", 0, 4, "コッコロ", 1, 209);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 105905, "敵は強大…ですが、心強い仲間の\nみなさまが一緒でございます\n…全員主さまとお知り合いなのは\n未だに信じられませんが…", "vo_empress_105901_002", 1, "", "vo_empress_105901_002", 0, 4, "コッコロ", 1, 210);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 105903, "まだこのような力が…！？\n主さま、ここはお下がりください\nたとえこの身に何があろうと、\nあなただけはお守りいたします…！", "vo_empress_105901_003", 2, "", "vo_empress_105901_003", 0, 4, "コッコロ", 1, 211);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 105902, "主さまとの絆がある限り\nわたくしは絶対に負けません！\nいついかなるときも、何があろうと\nわたくしが導いてみせます！", "vo_empress_105901_004", 3, "", "vo_empress_105901_004", 105901, 4, "コッコロ", 1, 212);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (3, 10000, 106001, "また陛下と戦うのね…大丈夫、一番\n大事なものが何なのかは分かってる\n…だから、あたしも負けないわ\n─陛下、よろしくお願いします！", "vo_empress_106001_001", 4005, 1, "vo_empress_106001_001", 0, 4, "キャル", 1, 213);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 106003, "この世界を好き勝手しようだなんて\nそういう連中に人生振り回されるの\nこちとらもううんざりなのよ！\n全員ぶっ飛ばしてやるんだから！", "vo_empress_106001_002", 1, "", "vo_empress_106001_002", 0, 4, "キャル", 1, 214);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 106003, "なんなのよあの力、反則でしょ…\nだけどさ、どんなに怖くたって\nあたしはここから退かないわ\n他に行くとこも、ないんだからっ…", "vo_empress_106001_003", 2, "", "vo_empress_106001_003", 0, 4, "キャル", 1, 215);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 106002, "絆の力でパワーアップ、なんて\nガラじゃないと思ってたけど…\n今だけは調子に乗らせてもらうわ\nもう負ける気がしないってねっ！", "vo_empress_106001_004", 3, "", "vo_empress_106001_004", 106001, 4, "キャル", 1, 216);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 106102, "晶に直してもらって\n天楼覇断剣も新品同然だ！\n気合い入れていくぞオクトー！\nはーっはっはっはー！", "vo_empress_106101_001", 1, "", "vo_empress_106101_001", 0, 4, "ノウェム", 1, 217);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 106101, "真那、覚悟しとけよ！\nオマエが積み上げてきた悪事…\nこの大悪党がまとめて\nぶっ壊してやるからな！", "vo_empress_106101_002", 1, "", "vo_empress_106101_002", 0, 4, "ノウェム", 1, 218);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 106103, "今までの借り…ここでまとめて\n返してやるって、決めてたんだ\nオマエだけは絶対に、許さない\n…オマエが、どれだけ強くても…っ", "vo_empress_106101_003", 2, "", "vo_empress_106101_003", 0, 4, "ノウェム", 1, 219);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 106102, "大悪党のプリンセス？\nなんだかよくわからないけど──\nとにかく、あの化け物ぶった斬りに\n行くぞ！　ついてこい！", "vo_empress_106101_004", 3, "", "vo_empress_106101_004", 106101, 4, "ノウェム", 1, 220);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 106401, "絶対に負けられない戦いね\nおいしいごはんと、本当の\nハッピーエンドのために\n気を引き締めていきましょう", "vo_empress_106401_001", 1, "", "vo_empress_106401_001", 0, 4, "シェフィ", 1, 221);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (3, 10000, 106403, "ミロク…まだ生きていたのね…！\nあの男は私が相手するわ\n兄さんの分もまとめて、\n今ここで借りを返さないと！", "vo_empress_106401_002", 4004, 1, "vo_empress_106401_002", 0, 4, "シェフィ", 1, 222);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 106401, "こんな力を隠してたなんて…！\n…まだよ。まだ諦めないわ\nどんな方法を使ってでも\nみんなだけは助けてみせる…！", "vo_empress_106401_003", 2, "", "vo_empress_106401_003", 0, 4, "シェフィ", 1, 223);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 106402, "不思議ね…あなたとの思い出で\n全身に力が満ちていくような気持ち\n…私たちが紡いできた絆を\n幻境竜后に見せてやりましょう", "vo_empress_106401_004", 3, "", "vo_empress_106401_004", 106401, 4, "シェフィ", 1, 224);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 106501, "おまえら、ケンカ売りたいんだろ？\nこの世界そのものに！\nならこっち向けよ。喧嘩屋のオレが\nまとめて買ってやるぜ！", "vo_empress_106501_001", 1, "", "vo_empress_106501_001", 0, 4, "カヤ", 1, 225);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 106501, "オレがドラゴン族なのも、\nこんな力を持ってるのも…きっと\n今日、この時のためだったんだ\nそうだろ？", "vo_empress_106501_002", 1, "", "vo_empress_106501_002", 0, 4, "カヤ", 1, 226);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 106503, "ウソだろ…オレが竦んじまってる…\nアイツのあの赤い眼から、眼を\nそらすんじゃねぇ…！　ドラゴン族\nのケンカ最強は…オレ様だろッ…！", "vo_empress_106501_003", 2, "", "vo_empress_106501_003", 0, 4, "カヤ", 1, 227);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 106501, "自分の力に、ずっとビビッてた\nでも今は何よりこの力を頼もしく\n感じるぜ。テメェをぶっ倒し…\n明日を迎えるための力がなァ！", "vo_empress_106501_004", 3, "", "vo_empress_106501_004", 106501, 4, "カヤ", 1, 228);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 106603, "どきやがれです！　最強ギャングが\nおまえのシマ分捕りにきたですよ！\nこんだけ仲間がいりゃ楽勝ですね♪\n尻尾巻いて逃げ出しやがれです！！", "vo_empress_106601_001", 1, "", "vo_empress_106601_001", 0, 4, "イノリ", 1, 229);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 106601, "あっちもゾロゾロつれてきやがり\nましたね…へんっ、このあたしが\nビビビビるとでもおお思うですか\n…お、お兄さん、どどどこです？", "vo_empress_106601_002", 1, "", "vo_empress_106601_002", 0, 4, "イノリ", 1, 230);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 106603, "…！　あたしと同じドラゴン族？\nボスをプリンセスナイトに従えて\nたとか…へんっ、信じねーです！\nまあボスより性悪そ…ぴゃああっ", "vo_empress_106601_003", 2, "", "vo_empress_106601_003", 0, 4, "イノリ", 1, 231);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 106602, "ふっふっふ～ん！　熱い力が\nどんどん溢れてくるですよっ！\nさあ、懲らしめてやるですっ！\nおしりペンペンですよ！", "vo_empress_106601_004", 3, "", "vo_empress_106601_004", 106601, 4, "イノリ", 1, 232);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 106701, "ふふっ、強そうな子がいっぱいだね\nそれじゃあ、誰が一番か決めよっか\nヴィーちゃんのプリンセスナイトで\n歴代最強は誰なのかを、ね♪", "vo_empress_106701_001", 1, "", "vo_empress_106701_001", 0, 4, "ホマレ", 1, 233);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 106701, "ヴィーちゃんてば、そんな子たちと\n一緒にいるほうが楽しいんだ～？\nじゃ、私たちも見せつけないとだね\n遠慮なくやっちゃおう☆　あははっ", "vo_empress_106701_002", 1, "", "vo_empress_106701_002", 0, 4, "ホマレ", 1, 234);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 106703, "これが、ヴィーちゃんの本気…\nとってもとってもすごいなぁ\n怖がりだからこそ、そんなに\n強くなれちゃったのかな…", "vo_empress_106701_003", 2, "", "vo_empress_106701_003", 0, 4, "ホマレ", 1, 235);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 106702, "残念だけど、ヴィーちゃん…\nもうゲームオーバーみたいだよ\nあなたとのどんなゲームも私には…\n全部ドキドキして、楽しかったな", "vo_empress_106701_004", 3, "", "vo_empress_106701_004", 106701, 4, "ホマレ", 1, 236);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 106802, "毎度、予想を超える困難ばかり\n押し寄せてくるんだからさ～\nま、アタシと少年が居る以上、\n好きにはさせないよ、ってね！", "vo_empress_106801_001", 1, "", "vo_empress_106801_001", 0, 4, "ラビリスタ", 1, 237);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (3, 10000, 106801, "よりによって真那まで相手かぁ…\nこりゃ一筋縄じゃいかなそうだ\n誰に対応するかは任せるけど、\n真那を相手取るなら頼ってよ", "vo_empress_106801_002", 4005, 1, "vo_empress_106801_002", 0, 4, "ラビリスタ", 1, 238);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 106801, "当然、奥の手も用意してくるよね\n次から次へと用意周到だこと…\nとはいえこっちも負けられない\nこの難局の突破口を探すとしよう！", "vo_empress_106801_003", 2, "", "vo_empress_106801_003", 0, 4, "ラビリスタ", 1, 239);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 106802, "七冠…しかも幻境竜后が相手なら\n手は抜けそうにもないね\nはは、でもアタシたちならきっと\n乗り越えられーる！　だよね少年♪", "vo_empress_106801_004", 3, "", "vo_empress_106801_004", 106801, 4, "ラビリスタ", 1, 240);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (3, 10000, 107001, "真那…ふふ、こんなところで相対\nすることになるとは。いつぞやの\n借り、返してあげますよ。用意は\nいいですね？　マサキも、貴方も", "vo_empress_107001_001", 4005, 1, "vo_empress_107001_001", 0, 4, "ネネカ", 1, 241);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 107001, "数で私たちを圧倒しようなど…\n底の浅い戦略ですね。返り討ちに\nしてあげましょう…この世界を\nまだ失うわけにはいきませんから", "vo_empress_107001_002", 1, "", "vo_empress_107001_002", 0, 4, "ネネカ", 1, 242);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 107001, "この力…計算外ではありますが\nそれは予想外という意味では\nありません。ええ、楽しみましょう\n不可能を解く、方程式の探求を", "vo_empress_107001_003", 2, "", "vo_empress_107001_003", 0, 4, "ネネカ", 1, 243);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 107002, "特等席で観察させてもらいましょう\n貴方の『心』という変数が\n『レジェンドオブアストルム』に\nどのような影響を与えるのかを…", "vo_empress_107001_004", 3, "", "vo_empress_107001_004", 107001, 4, "ネネカ", 1, 244);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 107101, "クリスティーナさんのご登場だよ☆\nあっははは……☆　またとない宴だ\n心行くまで愉しもうじゃあないか\n血で血を洗うダンス…滾るな♪", "vo_empress_107101_001", 1, "", "vo_empress_107101_001", 0, 4, "クリスティーナ", 1, 245);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (3, 10000, 107101, "真那さまがお出ましか…ワタシは\n本当に運がいいと見える♪　本気で\n刃を交える機会が巡ってくるなど\n願ってもない幸運だよ☆", "vo_empress_107101_002", 4005, 1, "vo_empress_107101_002", 0, 4, "クリスティーナ", 1, 246);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 107103, "…ここで退くなど興冷めだろう？\nたとえ足が竦んだとしても…退屈に\n食われるよりもよほどいい！\n最後まで愉しみつくしてやるさ…☆", "vo_empress_107101_003", 2, "", "vo_empress_107101_003", 0, 4, "クリスティーナ", 1, 247);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 107102, "誤算だったなあ、『幻境竜后』\n他の者ならいざ知らず…\nキサマを殺せる唯一の力\n手にしたのはこの『誓約女君』だ！", "vo_empress_107101_004", 3, "", "vo_empress_107101_004", 107101, 4, "クリスティーナ", 1, 248);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 110801, "ざーす。世界を救う系の光バイトで\n来たんすけど…あ、説明とかは\n大丈夫っす。慣れてるんでノリで\n入れます─おのれ世界の敵め！", "vo_empress_110801_001", 1, "", "vo_empress_110801_001", 0, 4, "クロエ", 1, 249);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (3, 10000, 110801, "なっつ、狐のねえさんいるじゃん\nまだ現役で悪モンやってたんだ\nてか中ボスポジに降格してるくね？\n世界の敵界隈、意外とせちがれーな", "vo_empress_110801_002", 4005, 1, "vo_empress_110801_002", 0, 4, "クロエ", 1, 250);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 110803, "なんかヤベーの出てきたな…\nこのカンジ、若干最悪っていうか\nぶっちゃけ流れ変わったくない？\nこっから捲るのは…結構ダルいわ", "vo_empress_110801_003", 2, "", "vo_empress_110801_003", 0, 4, "クロエ", 1, 251);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 110802, "ちょ、聞いて敵、ウケんだけど\nなんかうち主人公だったみたいだわ\n山場でヒロインに力託され系のやつ\nてわけで、勝ち確いただきでーす", "vo_empress_110801_004", 3, "", "vo_empress_110801_004", 110801, 4, "クロエ", 1, 252);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 110901, "ちぇるーん☆　ボス敵のみんな～！\n初めまして＆お久しブリリアント！\n世界の美少女ちえるんでっす！\n今からぼっこぼこにしてあげるね！", "vo_empress_110901_001", 1, "", "vo_empress_110901_001", 0, 4, "チエル", 1, 253);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 110901, "クリスＰの敵はカルミナの敵！\nカルミナの敵はなかよし部の敵！\nツアー全通めざして戦います！\n現場の平和はチエルが守る！", "vo_empress_110901_002", 1, "", "vo_empress_110901_002", 0, 4, "チエル", 1, 254);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 110903, "あ、あのう…ヤバくないです？\n敵のねえさん、急に年末歌合戦の\nラスボス衣装みたくなりましたけど\nえ、どーしよ…揚げます白旗？", "vo_empress_110901_003", 2, "", "vo_empress_110901_003", 0, 4, "チエル", 1, 255);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 110902, "世界の敵さん、ごめんちゃい！\nなんか愛だか絆だかの超理論的な\nアレでチエル覚醒しちゃいました！\nちぇるっと終わらせてあげますね！", "vo_empress_110901_004", 3, "", "vo_empress_110901_004", 110901, 4, "チエル", 1, 256);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 111001, "世界の危機だって？　何度目だね？\nざまあみろだよ、勝手に滅べば…\nなに、地球の危機？　この箱庭の\n話ではなく？　何ソレ一大事！", "vo_empress_111001_001", 1, "", "vo_empress_111001_001", 0, 4, "ユニ", 1, 257);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 111001, "お、おい…敵が多すぎないか…？\n端の方でわちゃわちゃしてるだけの\n数合わせ要員として来たのだが…\nどういう事だ、聞いてた話と違うぞ", "vo_empress_111001_002", 1, "", "vo_empress_111001_002", 0, 4, "ユニ", 1, 258);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 111003, "あばば…なんだ、あの奇怪な姿は…\nあれが理系をこじらせた者の末路か\n宇宙暗黒理系女…どうしてあんなに\nなるまで放っておいたんだ…", "vo_empress_111001_003", 2, "", "vo_empress_111001_003", 0, 4, "ユニ", 1, 259);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 111002, "はん、驕ったな理系の女王よ\n世界は君が思うほど四角くない\n高機能計算機の弾いた数字ごときで\nぼくと彼の行間までは測れまいよ！", "vo_empress_111001_004", 3, "", "vo_empress_111001_004", 111001, 4, "ユニ", 1, 260);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 118001, "ですからわたくしは商人で、\n戦いなどは不向き…などと\n言ってる場合ではありませんわね！\n参りますわよ、我が陛下のために！", "vo_empress_118001_001", 1, "", "vo_empress_118001_001", 0, 4, "クレジッタ", 1, 261);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 118003, "ああもうはあもう、あっちこっち\n滅茶苦茶にしてくださってからに！\n復興費用の賠償はどなたに\n請求すればよろしいのかしら！？", "vo_empress_118001_002", 1, "", "vo_empress_118001_002", 0, 4, "クレジッタ", 1, 262);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 118003, "でっか！？　でっっっっか！！！\n幻境竜后でしたかしら！？\nなんなんですのあの高層建築な方、\n建築基準法違反ですわよ～っ！？", "vo_empress_118001_003", 2, "", "vo_empress_118001_003", 0, 4, "クレジッタ", 1, 263);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 118002, "ホーッホッホッホ！　幻境竜后さん\n貴方にはいらっしゃるのかしら！\n利害でなくその理想のために\n命を賭ける、真実の忠臣が！", "vo_empress_118001_004", 3, "", "vo_empress_118001_004", 118001, 4, "クレジッタ", 1, 264);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 118101, "恐ろしくて強そうな音が…たくさん\nでも…きっと、大丈夫。あなたや、\nミソラちゃん…みんなが一緒で…\nあたたかい音も、たくさんだもの…", "vo_empress_118101_001", 1, "", "vo_empress_118101_001", 0, 4, "ランファ", 1, 265);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 118101, "緊張、してる…？　そ、それなら、\nわたしに、任せて…わたし、歌を、\n歌うわね…聴けばきっと、いつも\n通りの力を、出せると思うから…", "vo_empress_118101_002", 1, "", "vo_empress_118101_002", 0, 4, "ランファ", 1, 266);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 118103, "お、音と声が、すごい…\nなんて…なんて恐ろしいのかしら…\n…？　で、でも…この音。\n幻境竜后も、恐怖…している…？", "vo_empress_118101_003", 2, "", "vo_empress_118101_003", 0, 4, "ランファ", 1, 267);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 118102, "わたしの歌が、どれほど役立つかは\nわからない…そ、それでもっ、\nあなたの力になりたいの…だから\nわたし、精一杯、歌うわね…", "vo_empress_118101_004", 3, "", "vo_empress_118101_004", 118101, 4, "ランファ", 1, 268);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (3, 10000, 118201, "わー、ミロクさんや覇瞳皇帝さんも\nいるじゃないですか★\nそれじゃあわたしのガトリングで\nご挨拶といきましょっか♪", "vo_empress_118201_001", 4005, 1, "vo_empress_118201_001", 0, 4, "ミソラ", 1, 269);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 118201, "騎士さんと力を合わせればどんな\n敵もほにゃららら～★　って感じで\nなんとかなると思うんですよねー\nほら、主人公補正ってやつで♪", "vo_empress_118201_002", 1, "", "vo_empress_118201_002", 0, 4, "ミソラ", 1, 270);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 118202, "復讐って、イイコトですかね？\n悪いコトですかね？まぁとりあえず\nぶっ壊してから考えましょうか\nね、幻境竜后さん─", "vo_empress_118201_003", 2, "", "vo_empress_118201_003", 0, 4, "ミソラ", 1, 271);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 118202, "騎士さんに選んでもらっちゃいまし\nたし、いらない縁とはバイバイした\nいんですよねー♪　ってわけで、\nここで終わりにさせてもらいます★", "vo_empress_118201_004", 3, "", "vo_empress_118201_004", 118201, 4, "ミソラ", 1, 272);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 118501, "みなさんの力を信じて、\n私も全力でサポートします\n連携と創意工夫があれば、きっと\nこの難局も乗り越えられます！", "vo_empress_118501_001", 1, "", "vo_empress_118501_001", 0, 4, "カリン", 1, 273);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 118502, "過去最大級の強敵が現れました！\nギルド管理協会を代表して…\nあなたに討伐を依頼します！\n報酬はお望みのままに、ですよ♪", "vo_empress_118501_002", 1, "", "vo_empress_118501_002", 0, 4, "カリン", 1, 274);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 118503, "…っ。さすがの強敵ですね…\nだからこそ、焦りは禁物…です\nあらゆる事態を想定して、ギルドの\nみなさんを支援するのが私の仕事…", "vo_empress_118501_003", 2, "", "vo_empress_118501_003", 0, 4, "カリン", 1, 275);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 118502, "あなたと共に進めば\nどんな壁も越えられます\n私の、大切な人の無事を信じて…\n今こそ全力を尽くします！", "vo_empress_118501_004", 3, "", "vo_empress_118501_004", 118501, 4, "カリン", 1, 276);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 118601, "あんな奴らを野放しにしてたら\nこの世界が滅茶苦茶にされちゃう！\nでもまぁこれはこれでチャンスよ♪\n最っ高の悪戯の標的にしてあげる！", "vo_empress_118601_001", 1, "", "vo_empress_118601_001", 0, 4, "ネビア", 1, 277);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 118601, "私はただのガイド妖精、みんなに\n比べれば大した力も持ってない…\nでも悪戯妖精なりの意地があんのよ\nあいつらに一泡吹かせてやるわ♪", "vo_empress_118601_002", 1, "", "vo_empress_118601_002", 0, 4, "ネビア", 1, 278);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 118603, "幻境竜后、なんて力の持ち主なの\n正直きっついわ…でもまだやれる\n私はデータよ、壊れたって\nあんたを守る壁くらいにはなれる…", "vo_empress_118601_003", 2, "", "vo_empress_118601_003", 0, 4, "ネビア", 1, 279);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 118602, "覚悟しなさいっ！\n出来損ないの悪戯妖精をなめたら\n痛い目に遭うって教えてあげる\nさぁ、最高のショーの始まりよ！", "vo_empress_118601_004", 3, "", "vo_empress_118601_004", 118601, 4, "ネビア", 1, 280);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 122303, "むー！　いたずらっこの暴れんぼ\nさんたちは、ヴァンピィちゃんが\nきつーくおしおきしちゃうよ！\n真祖のおつとめですから！", "vo_empress_122301_001", 1, "", "vo_empress_122301_001", 0, 4, "ヴァンピィ", 1, 281);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 122302, "けんぞくはヴァンピィちゃんの\n背中に隠れてなさいっ。え？\n背中を守りたい？　うん、それなら\nよろしい！　一緒だよ、けんぞく！", "vo_empress_122301_002", 1, "", "vo_empress_122301_002", 0, 4, "ヴァンピィ", 1, 282);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 122303, "幻境竜后？　ふーんだ！\nベスちゃんのほーが、ずーっと\n強くてカッコいいですし！\nいくよっ、けんぞくぅ！", "vo_empress_122301_003", 2, "", "vo_empress_122301_003", 0, 4, "ヴァンピィ", 1, 283);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 122302, "ここはみんなの『いばしょ』！\n壊しちゃうなんて、許さないもん\nヴァンピィちゃん、本気で怒ったよ\nやっちゃうよ、けんぞく！", "vo_empress_122301_004", 3, "", "vo_empress_122301_004", 122301, 4, "ヴァンピィ", 1, 284);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 123002, "ほら、あんたは余計な心配しないの\nあいつらに好き勝手させないように\n全力でぶつかっていくだけよ\nあたしたちの未来のためにね♪", "vo_empress_123001_001", 1, "", "vo_empress_123001_001", 0, 4, "アメス", 1, 285);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 123001, "…あの連中も強くてやばいけど…\n一番やばいのは、こんなにたくさん\n女の子の知り合いがいる\nあんたかもしれないわね…", "vo_empress_123001_002", 1, "", "vo_empress_123001_002", 0, 4, "アメス", 1, 286);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 123003, "なんて相手なの…さすがに想定を\n超えてるわよ…こんなの卑怯よね\nだからってここで逃げやしないわよ\nせめて、あんたを守るくらいは…！", "vo_empress_123001_003", 2, "", "vo_empress_123001_003", 0, 4, "アメス", 1, 287);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 123002, "敵がどれだけ強くたって関係ないわ\nあんたの行く道はあたしが照らす\n迷ったらあたしを見なさい\nどこまでだって導いてあげる！", "vo_empress_123001_004", 3, "", "vo_empress_123001_004", 123001, 4, "アメス", 1, 288);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 123301, "『レギオンウォー』思い出すな～\nあん時は敵側だったけどー\n今回は騎士きゅんたちの隣で\nネアおねえちゃんもがんばるぞ～♡", "vo_empress_123301_001", 1, "", "vo_empress_123301_001", 0, 4, "ネア", 1, 289);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 123301, "だる～、激ヤバなテキばっかじゃん\n騎士きゅんパワー充電しねーと\nおねえちゃんもギリギリかもー\nとりま、ちゅっちゅ♡　してい？", "vo_empress_123301_002", 1, "", "vo_empress_123301_002", 0, 4, "ネア", 1, 290);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 123303, "激ヤバドラゴン、ガチしんどー…\nま、だからって負ける気ねーけど\nこーゆう時こそ、スライムの\n粘り強さの見せ所っしょ～　ね♪", "vo_empress_123301_003", 2, "", "vo_empress_123301_003", 0, 4, "ネア", 1, 291);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 123302, "ンフフフフ～♪　今のアタシ、\n騎士きゅんと一心同体ってやつ～？\nめちゃめちゃアガるわ～♪\n愛の力パねぇ～♡", "vo_empress_123301_004", 3, "", "vo_empress_123301_004", 123301, 4, "ネア", 1, 292);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 126401, "ビーッ！　ビーッ！\nあっちもこっちもそっちも\n強そうな人たちでいっぱいですっ！\nセンサーが壊れちゃいそう～っ！", "vo_empress_126401_001", 1, "", "vo_empress_126401_001", 0, 4, "クローチェ", 1, 293);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 126401, "世界が大変なことになってますっ！\nでもわたしたちは今までだって、\n大変な戦いを乗り越えてきましたっ\nきっと…ううん、絶対勝てますっ！", "vo_empress_126401_002", 1, "", "vo_empress_126401_002", 0, 4, "クローチェ", 1, 294);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 126403, "ビビービビビーッ！　…ひゃあっ！\nセンサーが壊れちゃいました…！\nしかも、照準が震えちゃって…\n…これが…この感情が、恐怖…？", "vo_empress_126401_003", 2, "", "vo_empress_126401_003", 0, 4, "クローチェ", 1, 295);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 126402, "今のわたしたちに、怖いものなんて\nありませんっ！　敵さんがどんなに\n強くても…わたしとナイトさんの\n特別なパワーは、もっと強いです！", "vo_empress_126401_004", 3, "", "vo_empress_126401_004", 126401, 4, "クローチェ", 1, 296);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 126501, "ジオ・テオゴニアの姫として\nこの星に生きる一個として\nこれ以上の蹂躙を許すわけには\nいきません。そうですね？　騎士", "vo_empress_126501_001", 1, "", "vo_empress_126501_001", 0, 4, "ライラエル", 1, 297);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (3, 10000, 126506, "穢らわしい、色狂いの山羊めが\n我が従僕を傀儡としてくれた借り、\n兆倍──否、京倍にして\n返してくれようぞ。崩雷夜天！", "vo_empress_126501_002", 4002, 1, "vo_empress_126501_002", 0, 4, "ライラエル", 1, 298);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 126503, "幻境竜后。迷いなく、圧倒的な力で\nわたしたちの調和を滅しようとする\nそんな力を、認めたくはないのに…\nなんて、困難な戦いなのでしょう…", "vo_empress_126501_003", 2, "", "vo_empress_126501_003", 0, 4, "ライラエル", 1, 299);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 126502, "この星には、あなたがいる…\n悪辣な侵略者と戦う理由など、\nただそれだけで十分です\n守りましょう。わたしたちの世界を", "vo_empress_126501_004", 3, "", "vo_empress_126501_004", 126501, 4, "ライラエル", 1, 300);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (3, 10000, 127701, "あそこにヴルムを傷つけた人が…！\n…騎士さん、絶対勝ちましょうね\nあの人たちのやったこと、私\n絶対ぜったい許しませんから！", "vo_empress_127701_001", 4002, 1, "vo_empress_127701_001", 0, 4, "リンド", 1, 301);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 127701, "騎士さんたちと出会えたこの世界を\n悪いことになんか使わせません\n作り物だなんて信じられませんけど\n失っちゃいけないものはわかります", "vo_empress_127701_002", 1, "", "vo_empress_127701_002", 0, 4, "リンド", 1, 302);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 127703, "まだこんな力が残ってるの…！？\n考えなきゃ、私にできること…\n何か…何かないの…！？\nまた私、何もできないの…？", "vo_empress_127701_003", 2, "", "vo_empress_127701_003", 0, 4, "リンド", 1, 303);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 127702, "あなたが側にいてくれるから、\n私もこうして戦えます\nチョロいって言われてもいいです\n私にとって、大切なひとですから", "vo_empress_127701_004", 3, "", "vo_empress_127701_004", 127701, 4, "リンド", 1, 304);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 127801, "…正直、サボりとかじゃなくて…\nぜんぜん身体はきついです。でも…\n姉貴やみんなと過ごすこの世界は\n誰にも壊させやしませんから…！", "vo_empress_127801_001", 1, "", "vo_empress_127801_001", 0, 4, "ヴルム", 1, 305);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (3, 10000, 127801, "騎士さん…アルシャトのこと\nあたしにも一発殴らせてください\nふざけた真似してくれたお礼…\n倍にして返してやりますよ", "vo_empress_127801_002", 4002, 1, "vo_empress_127801_002", 0, 4, "ヴルム", 1, 306);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 127803, "冗談きついです、こんなの…\n勝てっこないじゃないですか\nあたしだってドラゴン族なのに\nこれほどまでに差があるだなんて…", "vo_empress_127801_003", 2, "", "vo_empress_127801_003", 0, 4, "ヴルム", 1, 307);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 127802, "もう後先考えずにいきますよ\n面倒見てくれる人がここにいるので\nあたしと騎士さんが揃えば\n無敵だってとこ見せてやります", "vo_empress_127801_004", 3, "", "vo_empress_127801_004", 127801, 4, "ヴルム", 1, 308);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (3, 10000, 129001, "覇瞳皇帝…わたしの邪魔をするなら\nかつてのように、消去するだけ\nミロクも…わたしを草野優衣の\n複製と呼んだこと、後悔させてやる", "vo_empress_129001_001", 4005, 1, "vo_empress_129001_001", 0, 4, "エリス", 1, 309);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 129001, "管理者の座は失っても\nわたしの意志は揺らがない…\n騎士クンの物語を紡ぐために…\nそれが、わたしの全てだから", "vo_empress_129001_002", 1, "", "vo_empress_129001_002", 0, 4, "エリス", 1, 310);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 129003, "これが七冠、幻境竜后の全力…\n管理者だったかつてのわたしを、\n超えるほどの脅威…でも、\n騎士クンだけは、守ってみせる…", "vo_empress_129001_003", 2, "", "vo_empress_129001_003", 0, 4, "エリス", 1, 311);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 129002, "孤独も絶望も越えてきた\nもうどんな闇にも迷わない\n騎士クンが隣にいる限り\nわたしは、負けない", "vo_empress_129001_004", 3, "", "vo_empress_129001_004", 129001, 4, "エリス", 1, 312);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 129601, "リアを──媛を、傷つけたひとたち\n笑ってられるのも今だけです──\nアルラウネの棘の鋭さ、\n教えてあげますから──", "vo_empress_129601_001", 1, "", "vo_empress_129601_001", 0, 4, "アネモネ", 1, 313);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 129601, "騎士のひと──背中は、任せます\n貴方のこと、\n媛と同じくらい、信じてるので──\n自分でも、びっくりですけど", "vo_empress_129601_002", 1, "", "vo_empress_129601_002", 0, 4, "アネモネ", 1, 314);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 129603, "私、ずっと抗ってきたんです\nそのために、強くなったはず──\nだから──諦めたく、ないです…", "vo_empress_129601_003", 2, "", "vo_empress_129601_003", 0, 4, "アネモネ", 1, 315);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 129601, "体が熱くて、思考がまとまらなくて\nなのに負ける気がしない──なんて\nよくわからないです。どうしてか、\n後で教えてください──騎士のひと", "vo_empress_129601_004", 3, "", "vo_empress_129601_004", 129601, 4, "アネモネ", 1, 316);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 129701, "難敵強敵揃い踏みなれど\nわっちらが退く理はありんせん\n騎士殿や、手を携えて此度の争乱\n鎮めて見せましょう也", "vo_empress_129701_001", 1, "", "vo_empress_129701_001", 0, 4, "ネフィ＝ネラ", 1, 317);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 129701, "今のわっちが萎弱であろうとて\n貴様等如き梟悪に斃される訳には\nゆかぬ也。再び足甲を舐めさせ\n地に臥すまで仕置きを致しんしょう", "vo_empress_129701_002", 1, "", "vo_empress_129701_002", 0, 4, "ネフィ＝ネラ", 1, 318);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 129703, "我が矜持『不退転』─如何なる敵で\nあろうとも揺らぐ仕儀はなし。斯様\nな邪竜程度、退けむと思い侍りしが\n─難儀な由、残念至極─…", "vo_empress_129701_003", 2, "", "vo_empress_129701_003", 0, 4, "ネフィ＝ネラ", 1, 319);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 129702, "参りまする也、騎士殿や\n懼るること等何一つ御座りんせん\n唯わっちらの勇儀を以て、此の星の\n明日を再び…掌中に致しんしょう", "vo_empress_129701_004", 3, "", "vo_empress_129701_004", 129701, 4, "ネフィ＝ネラ", 1, 320);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (3, 10000, 130001, "─おや、フレイヤじゃないか\nずいぶん様変わりしたようだが\n今の方がアタシとしちゃ好みだね\nお礼参りのしがいもあるってもんさ", "vo_empress_130001_001", 4003, 1, "vo_empress_130001_001", 0, 4, "ヤマト", 1, 321);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 130001, "…フゥン？　あっちもこっちも\n『王家の装備』を持ってるらしいね\n宝の山ってのはこのことかい\nまとめて搔っ攫ってやろうかね…！", "vo_empress_130001_002", 1, "", "vo_empress_130001_002", 0, 4, "ヤマト", 1, 322);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 130003, "ちっ…、幻境竜后つったかい\n世界を奪おうってのも冗談じゃ\nなさそうだ。…ワカナ、フブキ…\nお前たちだけでも、逃げな…", "vo_empress_130001_003", 2, "", "vo_empress_130001_003", 0, 4, "ヤマト", 1, 323);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 130002, "アタシらの住み家を奪おうだぁ？\nハッ、笑わせてくれるね\n盗賊は盗むモンであって、\n盗まれるモンじゃあないンだよ！", "vo_empress_130001_004", 3, "", "vo_empress_130001_004", 130001, 4, "ヤマト", 1, 324);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 130101, "つ、強そうな人たちがたくさん…\nなのに姉さんもフブキちゃんも\nやる気満々だし…\nわたし、どうすればいいのぉ～っ", "vo_empress_130101_001", 1, "", "vo_empress_130101_001", 0, 4, "ワカナ", 1, 325);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 130101, "きっと、長期戦になりますよね…\nあ、あの…ご飯、食べませんか？\nお腹が空くといけないと思って、\n作ってきたので…よろしければっ", "vo_empress_130101_002", 1, "", "vo_empress_130101_002", 0, 4, "ワカナ", 1, 326);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 130103, "む…むりっ！　無理ですよ～っ！\nあんなおっきいドラゴンなんて、\n勝てるわけないじゃないですかっ\nに、逃げちゃいましょ、ねっ…！？", "vo_empress_130101_003", 2, "", "vo_empress_130101_003", 0, 4, "ワカナ", 1, 327);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 130102, "と、盗られるぐらいなら盗るのが\n【バンディ・シスターズ】流ですっ\n騎士さん、わたしたちの未来を\n掴み取りにいきましょう…っ！", "vo_empress_130101_004", 3, "", "vo_empress_130101_004", 130101, 4, "ワカナ", 1, 328);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 130201, "だる～、ささっと片付けてきてよ～\nムリ？　知ってる～だってザコザコ\nお兄さんだもんね♪　しょーがない\n助けてあげよっかな～？きゃはは♡", "vo_empress_130201_001", 1, "", "vo_empress_130201_001", 0, 4, "フブキ", 1, 329);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 130201, "あの陰気ダサダサメガネさー、\n仲間集めてチョーシ乗ってねー？\nザコは何匹集まったってザコだって\nフブキちゃんが教えてあげまーす♪", "vo_empress_130201_002", 1, "", "vo_empress_130201_002", 0, 4, "フブキ", 1, 330);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 130203, "ふぇぇ…まじムリ、アイツムリ～！\n全然ラスボスってカンジじゃん！？\nぼくお家かえるぅ～っ！\nお兄さんも一緒にかえろっ、ねっ？", "vo_empress_130201_003", 2, "", "vo_empress_130201_003", 0, 4, "フブキ", 1, 331);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 130202, "お兄さん、やる気漲っちゃってる？\nだよねー、世界が滅んじゃったら\nぼくとも永遠のお別れなんだし？\n必死になるのもトーゼンっしょ～♡", "vo_empress_130201_004", 3, "", "vo_empress_130201_004", 130201, 4, "フブキ", 1, 332);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 130901, "はわっ！？　すっごくすっごく\n悪そうな人達いっぱいですますぅ！\nかばばん君、警備員モードです！\nぴっぴーーーー！", "vo_empress_130901_001", 1, "", "vo_empress_130901_001", 0, 4, "クルル", 1, 333);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 130901, "この戦いが終わったら、みなさんと\nパークで凱旋パレードですぅ♪\n…ふぇっ？\n気が早いですますか？", "vo_empress_130901_002", 1, "", "vo_empress_130901_002", 0, 4, "クルル", 1, 334);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 130903, "はわわっ！　幻境竜后さん、\n強そうすぎですっ…でもっ！\nやっと再建したパークも世界も\nぜったい壊させないですよ～っ！", "vo_empress_130901_003", 2, "", "vo_empress_130901_003", 0, 4, "クルル", 1, 335);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 130902, "ヒーローさんのこと、\nクルルの全部でお助けしますです！\nジオ・テオゴニアでも、どんな世界\nでも…ずっと、ず～っとですっ！", "vo_empress_130901_004", 3, "", "vo_empress_130901_004", 130901, 4, "クルル", 1, 336);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 132301, "なっなんなのよこいつらっ！\nダーリンとの恋路を邪魔する気…？\nそんなことさせないわ…だって、\n二人の恋はエターナルですからっ！", "vo_empress_132301_001", 1, "", "vo_empress_132301_001", 0, 4, "ルイズマリー", 1, 337);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 132301, "愛情×愛情＝無限大…\n遂に錬金術の神髄に辿り着いたわ…\nさあ…お見舞いしてやりましょう！\n私とダーリンの究極錬成をっ！", "vo_empress_132301_002", 1, "", "vo_empress_132301_002", 0, 4, "ルイズマリー", 1, 338);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 132303, "あ、あなたがどんなに強くても、\n私は逃げないわ！　ダーリンに\nちょっかいかける奴は絶対に\n許さないって決めてるから…っ！！", "vo_empress_132301_003", 2, "", "vo_empress_132301_003", 0, 4, "ルイズマリー", 1, 339);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 132302, "悪いけど速攻で終わらせちゃうわ！\n早く帰ってダーリンと心行くまで\n破廉恥な乳繰り合い…じゃなくて！\n愛を確かめ合うんだからっ！", "vo_empress_132301_004", 3, "", "vo_empress_132301_004", 132301, 4, "ルイズマリー", 1, 340);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 132401, "わわっ、敵がいっぱい！\nこれがクワガタだったら最高…よし\n新種のクワガタって事にしちゃお！\nあははっ！　待て待て～っ！！", "vo_empress_132401_001", 1, "", "vo_empress_132401_001", 0, 4, "イロハ", 1, 341);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 132401, "あはは、まだまだ出てくるね～！\nなら新しい技いっぱい\n試しちゃおっか…さあ、いくよ！\n──イスルギ流奥義っ！！", "vo_empress_132401_002", 1, "", "vo_empress_132401_002", 0, 4, "イロハ", 1, 342);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 132401, "あのおねーさんもなかなか良いツノ\n持ってるねえ♪　イロハが勝ったら\nルイちゃんと二人でクワガタ相撲\nごっこやってもらおっと！", "vo_empress_132401_003", 2, "", "vo_empress_132401_003", 0, 4, "イロハ", 1, 343);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 132402, "おねーさんがどんなに強くたって\nイロハは絶対に負けない！\nおじちゃんが見ててくれてる時の\nイロハは、サイキョーなんだから！", "vo_empress_132401_004", 3, "", "vo_empress_132401_004", 132401, 4, "イロハ", 1, 344);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 132501, "いや無理無理、戦いとか苦手過ぎる\n…でも君となら、奇跡起こせるかも\n…うわやば、今の忘れて\n若者みたいなこと言っちゃったよ…", "vo_empress_132501_001", 1, "", "vo_empress_132501_001", 0, 4, "ソノ", 1, 345);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 132501, "敵、まだいっぱいいるじゃん…\nはあ…残業したくないけど頑張るか\n全部終わったら君からのマッサージ\n期待しとくから、ね", "vo_empress_132501_002", 1, "", "vo_empress_132501_002", 0, 4, "ソノ", 1, 346);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 132503, "はあ…はあ…幻境竜后だっけ？\nルイちゃんの錬金術より\n出鱈目な強さだね…！\nでもまだまだ諦めない…いくよ！", "vo_empress_132501_003", 2, "", "vo_empress_132501_003", 0, 4, "ソノ", 1, 347);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 132502, "こんなに強い敵が相手でも\n諦めなきゃ勝てるんだって\n教えてくれたのは君だよ\nふふ…ありがとね、若者♪", "vo_empress_132501_004", 3, "", "vo_empress_132501_004", 132501, 4, "ソノ", 1, 348);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 133001, "うーわ。あっちもこっちも\nボス級だらけじゃないですか\nま、ヴァイオレット姫には\n指一本触れさせませんけどね", "vo_empress_133001_001", 1, "", "vo_empress_133001_001", 0, 4, "グレイス", 1, 349);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (3, 10000, 133003, "リーザ…今度こそ、決着の時ね\nいくら頭数を揃えても私は…いえ\n私と騎士氏は絶対に負けないわ\nこの槍で、冥界に送り返してあげる", "vo_empress_133001_002", 4001, 1, "vo_empress_133001_002", 0, 4, "グレイス", 1, 350);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 133003, "ぐっ…圧倒的ですね『幻境竜后』\nですが…決してあきらめません\n私には、生きていてほしい人が\nたくさんいますので…！", "vo_empress_133001_003", 2, "", "vo_empress_133001_003", 0, 4, "グレイス", 1, 351);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 133002, "とてつもない強敵を前にしてるのに\nまるで恐怖心を感じません…\n…恋とは、心霊現象よりも\n不思議なものらしいですよ", "vo_empress_133001_004", 3, "", "vo_empress_133001_004", 133001, 4, "グレイス", 1, 352);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 133101, "恐るべき方々ばかりです…\nですがわたくしは絶対に退きません\nジオ・ニヴルヘルの姫として\nこの世界を守ると決めたのです！", "vo_empress_133101_001", 1, "", "vo_empress_133101_001", 0, 4, "ヴァイオレット", 1, 353);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (3, 10000, 133101, "リーザ…どうしてもわたくしたちの\n前に立ちはだかるというのですね\nならばわたくしも覚悟を決めました\nこの手であなたを、倒します…！", "vo_empress_133101_002", 4001, 1, "vo_empress_133101_002", 0, 4, "ヴァイオレット", 1, 354);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 133103, "これが、彼女の本気の力…！\n異質で…故に、とても寂しい…\n本当の意味で彼女に届く声が、\nこの世界に存在するのでしょうか…", "vo_empress_133101_003", 2, "", "vo_empress_133101_003", 0, 4, "ヴァイオレット", 1, 355);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 133102, "あなたとの「繋がり」がある限り\n死が牙を剥くことはありません\n手を取り合い、共に参りましょう\nわたくしたちの未来のために！", "vo_empress_133101_004", 3, "", "vo_empress_133101_004", 133101, 4, "ヴァイオレット", 1, 356);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 133601, "フンっ、次から次へと…！　なら\n思う存分、大暴れしてやるから♪\nやっちゃうわよ、メドゥシアナ！\nアンタも！！", "vo_empress_133601_001", 1, "", "vo_empress_133601_001", 0, 4, "メドゥーサ", 1, 357);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 133601, "どこの誰だか知らないけれど、\nアタシの魔眼でまとめて石に…って\nきゃああああ！　こんなバケモン級\nなら先に教えときなさいよ～っ！", "vo_empress_133601_002", 1, "", "vo_empress_133601_002", 0, 4, "メドゥーサ", 1, 358);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 133603, "な…なんなの、アイツの『眼』…\nでもねっ、アタシはメドゥーサ\nゴルゴーンの、お姉ちゃんの妹よ！\n睨みあいで負けるわけがないわ！", "vo_empress_133601_003", 2, "", "vo_empress_133601_003", 0, 4, "メドゥーサ", 1, 359);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 133602, "知ってる？　蛇って執念深いのよ\nこの『眼』で見つけてやったわ\n幻境竜后、アンタが一番恐れること\nアタシとこいつが手をつなぐこと！", "vo_empress_133601_004", 3, "", "vo_empress_133601_004", 133601, 4, "メドゥーサ", 1, 360);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 134701, "この大地と大空を守るため、\n人の子らだけに任せてはおけません\n鳳凰のはばたきで、その野望ごと\n跡形もなく吹き飛ばしましょう！", "vo_empress_134701_001", 1, "", "vo_empress_134701_001", 0, 4, "ホウオウ", 1, 361);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 134701, "さあ皆さん、ここが正念場です！\n私がいれば楽勝圧勝間違いなし！\n…えっ？　私が先頭？　えーと…\nあっちょっと待って押さないで！", "vo_empress_134701_002", 1, "", "vo_empress_134701_002", 0, 4, "ホウオウ", 1, 362);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 134703, "羽が散って、ちっ、力が…\n幻境竜后、やるではないですか…\nしかし、私も不死鳥と呼ばれた身…\nただでやられは…ぴ、ぴよぉぉ～…", "vo_empress_134701_003", 2, "", "vo_empress_134701_003", 0, 4, "ホウオウ", 1, 363);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 134702, "幻境竜后、でしたか？\nあなたも運のない方ですね\n今の私は輪廻史上最強の鳳凰\nその鱗一つ残さず焼き尽くします！", "vo_empress_134701_004", 3, "", "vo_empress_134701_004", 134701, 4, "ホウオウ", 1, 364);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 134901, "ヲ～ッホッホ！　どいつもこいつも\n大層なおツラ構えしてますけどぉ？\nあたくし様の敵じゃありませんわ！\nほら馬ボーン！　お強化なさいな！", "vo_empress_134901_001", 1, "", "vo_empress_134901_001", 0, 4, "カノン", 1, 365);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 134901, "いってぇ～ですわ！　あたくし様の\nお美しいお肌を傷つけましたわね！\nまとめてお成敗して差し上げますわ\nついてらっしゃいな！　馬ボーン！", "vo_empress_134901_002", 1, "", "vo_empress_134901_002", 0, 4, "カノン", 1, 366);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 134903, "なんてタマですの…アースハイドラ\nよりデカいなんて聞いてませんわ！\nでも…ここでお尻尾巻いて逃げる\nなら、死んだ方がマシですわ…！", "vo_empress_134901_003", 2, "", "vo_empress_134901_003", 0, 4, "カノン", 1, 367);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 134902, "幻境竜后とやら、お覚悟なさいな\nあたくしと馬ボーンの前に立つなど\n100億万年お早いですわ！\n華麗にお成敗して差し上げますわ♪", "vo_empress_134901_004", 3, "", "vo_empress_134901_004", 134901, 4, "カノン", 1, 368);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 135501, "来たね、お姉さんの出番ってやつ♪\nキミと一緒に戦えるなんて、あたし\nテンション最高潮だよ！　あははっ\nさ、思いっきり暴れちゃおっか！", "vo_empress_135501_001", 1, "", "vo_empress_135501_001", 0, 4, "アイラ", 1, 369);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (3, 10000, 135501, "あれが…覇瞳皇帝のオリジナルだね\nま、関係ないや。本物でも偽物でも\n今度こそ決着つけてあげるから！\nお姉さんの拳…燃え盛ってるよー！", "vo_empress_135501_002", 4005, 1, "vo_empress_135501_002", 0, 4, "アイラ", 1, 370);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 135503, "幻境竜后…とんでもない相手だね\nあたしの拳だって届かないかも…\nそれでも、燃え尽きるまで戦うよ\nキミが信じてくれてる限り、ね！", "vo_empress_135501_003", 2, "", "vo_empress_135501_003", 0, 4, "アイラ", 1, 371);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 135502, "キミがいれば怖いものなし！\nお姉さん今、燃えに燃えてるよっ\n太陽より熱く燃える拳で…\n全部まとめてぶっ飛ばす！", "vo_empress_135501_004", 3, "", "vo_empress_135501_004", 135501, 4, "アイラ", 1, 372);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 135601, "どれほどの逆風の中にいても、\n諦めてはならない…そうだろう？\nかつて私が、他でもないキミたちに\nそう教えてもらったんだ…", "vo_empress_135601_001", 1, "", "vo_empress_135601_001", 0, 4, "シナツ", 1, 373);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 135601, "私はこの世界の人々と出会い、\n失ったはずの希望を見つけられた\n今度は私が、皆に希望を届ける番だ\nこの刃、存分に振るわせてくれ", "vo_empress_135601_002", 1, "", "vo_empress_135601_002", 0, 4, "シナツ", 1, 374);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 135603, "幻境竜后…私たちの世界を創造し、\nそして滅ぼそうとした張本人か…！\nその力がどんなに強大だとしても…\n私は…絶対に逃げたりなどしない！", "vo_empress_135601_003", 2, "", "vo_empress_135601_003", 0, 4, "シナツ", 1, 375);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 135602, "私の刃に、もはや一片の曇りもない\n皆と生きる未来を守り抜くために\n戦いつづける…ただそれだけだ\n─道を阻む者は全て斬り伏せる！", "vo_empress_135601_004", 3, "", "vo_empress_135601_004", 135601, 4, "シナツ", 1, 376);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (3, 10000, 135801, "リ、リ、リーザちゃ…！\nリーザちゃはあてのこと、ヘタレの\nホジナシって思ってっかもだけど…\n前より成長したとこ、見せっから！", "vo_empress_135801_001", 4001, 1, "vo_empress_135801_001", 0, 4, "ユキノ", 1, 377);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 135801, "田舎者で世間知らずなあてだけど…\n騎士さと一緒にいろんなとこ行って\n大切な思い出、いっぱいできたよ…\nだから守りてぇんだ、この世界…！", "vo_empress_135801_002", 1, "", "vo_empress_135801_002", 0, 4, "ユキノ", 1, 378);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 135803, "あ、あても、ちったぁでけぇけど…\n幻境竜后、で、でっかすぎ…！\nそ、それに竜まで…！　炎浴びたら\nあて、溶けちまうよぅ…！", "vo_empress_135801_003", 2, "", "vo_empress_135801_003", 0, 4, "ユキノ", 1, 379);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 135802, "「あてなんか」なんて、考えね…\n騎士さが信じてくれるなら、\nあてだって自分のこと、信じるよ\nあてと騎士さなら大丈夫、って…！", "vo_empress_135801_004", 3, "", "vo_empress_135801_004", 135801, 4, "ユキノ", 1, 380);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (3, 10000, 135903, "リザ公…手前ェどの面下げて\n俺の前に出てきやがった\nまァいいさ、何聞いても今更だ\nここで落とし前つけてもらうぜ", "vo_empress_135901_001", 4001, 1, "vo_empress_135901_001", 0, 4, "サツキ", 1, 381);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 135901, "いつ死んでもいいなんて\nもう思っちゃいねぇさ\nこの悪玉どもより、図太くしぶとく\n生き抜いてやろうじゃねぇか", "vo_empress_135901_002", 1, "", "vo_empress_135901_002", 0, 4, "サツキ", 1, 382);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 135901, "あれが幻境竜后か…\nハンパじゃねェや\nしゃあねぇ、こうなりゃ一丁\n死に花咲かすとするか", "vo_empress_135901_003", 2, "", "vo_empress_135901_003", 0, 4, "サツキ", 1, 383);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 135902, "世界だの未来だの現実だの…\n重いったらありゃしねぇぜ\n潰れるなよ、騎士公\n俺も一緒に担いでやっからさ", "vo_empress_135901_004", 3, "", "vo_empress_135901_004", 135901, 4, "サツキ", 1, 384);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 136001, "騎士さま、どうかご安心を…\nどれだけ厳しい運命が待って\nいたとしても…あなたのことは、\nわたしの糸が必ずお守りします", "vo_empress_136001_001", 1, "", "vo_empress_136001_001", 0, 4, "アラクネ", 1, 385);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (3, 10000, 136001, "…？　あの金髪の女性、なんだか\n見覚えあるような気が…いえ\n騎士さまの敵は、わたしの敵です\nそれだけです…", "vo_empress_136001_002", 4003, 1, "vo_empress_136001_002", 0, 4, "アラクネ", 1, 386);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 136003, "あれが幻境竜后さま…\nなんという恐るべき力\n…騎士さま、わたしの後ろに\n一度くらいは、庇えるはずです…", "vo_empress_136001_003", 2, "", "vo_empress_136001_003", 0, 4, "アラクネ", 1, 387);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 136002, "騎士さまという光が、わたしに力を\n与えてくれるのです。ともに未来を\n歩むためにも…この戦いに\n必ず勝ちましょう、騎士さま", "vo_empress_136001_004", 3, "", "vo_empress_136001_004", 136001, 4, "アラクネ", 1, 388);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 136201, "強そうな敵さんがいっぱい～っ！？\nこーなったら、ウルトラとっておき\nドーナツ！　ちょっと湿気てるけど\n…はい騎士ちゃん、あーんっ♪", "vo_empress_136201_001", 1, "", "vo_empress_136201_001", 0, 4, "ナーナ", 1, 389);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 136201, "ナーナだって頑張れるんだよっ！\n騎士ちゃんに、そう教わったもん！\nだから、すごく怖いけど…でもっ…\nナーナ、逃げたりしないよぉっ！", "vo_empress_136201_002", 1, "", "vo_empress_136201_002", 0, 4, "ナーナ", 1, 390);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 136201, "うぅ…あ、足が震えてきちゃった…\nでも動かなきゃ、戦わなきゃっ…\nわかってるのに、でもでもぉ…\nうえぇぇん、やっぱり怖いぃぃ！", "vo_empress_136201_003", 2, "", "vo_empress_136201_003", 0, 4, "ナーナ", 1, 391);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 136202, "今のナーナはよわよわウサギじゃ\nないんだよ。騎士ちゃんのためなら\nどんな敵さんだってやっつけちゃう\nつよつよウサギなんだから！", "vo_empress_136201_004", 3, "", "vo_empress_136201_004", 136201, 4, "ナーナ", 1, 392);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (3, 10000, 136903, "リーザ姉しゃまが裏切ったなんて\nあたち、信じたくないでしゅ…！\nだから直接聞きにいきましゅ\n吸盤ぜんぶで捕まえてでも…！", "vo_empress_136901_001", 4001, 1, "vo_empress_136901_001", 0, 4, "ルルィ", 1, 393);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 136901, "姫姉しゃまも騎士しゃんも\nみなしゃん戦ってるんでしゅ\nあたちだって負けましぇん！\n一生懸命がんばりましゅ～！", "vo_empress_136901_002", 1, "", "vo_empress_136901_002", 0, 4, "ルルィ", 1, 394);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 136903, "あ、あの方、こわいでしゅ…！\n丸呑みにされちゃいそうでしゅっ\nうじゅ…がんばりたいでしゅが…\n震えが止まらないでしゅ…！", "vo_empress_136901_003", 2, "", "vo_empress_136901_003", 0, 4, "ルルィ", 1, 395);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 136902, "あたちは強くないでしゅけど\n騎士しゃんとの約束がありましゅ\nだから誰にも負けましぇん！\nいっちょに、守りましゅよ！", "vo_empress_136901_004", 3, "", "vo_empress_136901_004", 136901, 4, "ルルィ", 1, 396);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 139501, "これから挑む敵がどれだけ強いと\nしても、勇往邁進していきます\nですからこの戦いでも、兄様の\nおそばで戦わせてくださいませ", "vo_empress_139501_001", 1, "", "vo_empress_139501_001", 0, 4, "リリ", 1, 397);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (3, 10000, 139503, "幻境竜后の手先、アルシャト…！\nリアさんやヴルム様を陥れた貴方を\n決して許す訳には参りません！\n不倶戴天─ここで成敗致します！", "vo_empress_139501_002", 4002, 1, "vo_empress_139501_002", 0, 4, "リリ", 1, 398);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 139503, "幻境竜后の力…これほどまでに\n強力無比だとは…で、ですが…\n何があろうとわたくしは兄様を\nお守りします…命に代えても、必ず", "vo_empress_139501_003", 2, "", "vo_empress_139501_003", 0, 4, "リリ", 1, 399);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 139502, "兄様への想いと、重ねてきた大切な\n時間が、たくさんの勇気と限界を\n超える奇跡をくれました。全ての人\nを救うため、参りましょう兄様…！", "vo_empress_139501_004", 3, "", "vo_empress_139501_004", 125801, 4, "リリ", 1, 400);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 139603, "お兄さん、もし怪我しちゃっても\nすぐに治癒しますからご安心を！\nわたし決めましたから…もう二度と\n自分自身から逃げないって…！", "vo_empress_139601_001", 1, "", "vo_empress_139601_001", 0, 4, "クリア", 1, 401);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (3, 10000, 139603, "…アルシャトさん…\n謝ったって許してあげませんよ？\nあなたの前では、わたしちょっと\nいい子じゃいられませんから…っ！", "vo_empress_139601_002", 4002, 1, "vo_empress_139601_002", 0, 4, "クリア", 1, 402);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 139603, "うぅっ…これが本気の幻境竜后…！\n…こんなの勝てっこありませんよ…\n…せめてお兄さんだけでも…なんて\n最後まで…諦めませんからっ…！", "vo_empress_139601_003", 2, "", "vo_empress_139601_003", 0, 4, "クリア", 1, 403);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 139601, "お兄さんの気持ちが胸に溢れて…\nあ、えへへ…なんだか視界が\n滲んできちゃいました…♪\nわたしはもう、負けませんよ…っ！", "vo_empress_139601_004", 3, "", "vo_empress_139601_004", 126001, 4, "クリア", 1, 404);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 139701, "てき、いっぱい、しかも、つよすぎ\nけど、まけないよ\nお兄のほっぺ、たべて\nふるぱわー", "vo_empress_139701_001", 1, "", "vo_empress_139701_001", 0, 4, "プレシア", 1, 405);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 139701, "ん\nまだまだ、いける\nお兄、パパ、なかま、いる\nむしゃぶるい", "vo_empress_139701_002", 1, "", "vo_empress_139701_002", 0, 4, "プレシア", 1, 406);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 139703, "しょうり、みえない\nせいぎ、まもれない\nそんなの、いや\nあきらめないよ、さいごまで", "vo_empress_139701_003", 2, "", "vo_empress_139701_003", 0, 4, "プレシア", 1, 407);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 139702, "て、つなぐ\nせいめいりょく、たかまる\nぜったいしょうり！", "vo_empress_139701_004", 3, "", "vo_empress_139701_004", 126101, 4, "プレシア", 1, 408);
INSERT INTO `v1_732b8d02188bb86a17f64b8a52c13d0e2e5ea4bb8420c34b9a395b961a0218c7` VALUES (5, "", 140301, "七冠、幻境竜后──LoAの開発者\nあんたにコワいコト教えてあげるわ\n些細なバグと思って放置したら\nゲームを壊すこともあるってね…♪", "vo_empress_140301_004", 3, "", "vo_empress_140301_004", 140301, 4, "ティア", 1, 409);
